import { create } from 'zustand';
import type { Attachment, Contact } from '../data/types';
import { uid } from '../lib/format';

export interface ComposeWin {
  id: string;
  draftId: string;
  minimized: boolean;
  maximized: boolean;
}

export interface ToastAction {
  label: string;
  run: () => void;
}

export interface Toast {
  id: string;
  message: string;
  actions?: ToastAction[];
  duration?: number;
}

export interface Notice {
  id: string;
  from: Contact;
  title: string;
  body: string;
  threadId: string;
}

export interface LabelDialogState {
  mode: 'create' | 'edit';
  labelId?: string;
  applyTo?: string[];
  /** Move the conversations into the new label (remove from Inbox) instead of just labelling. */
  move?: boolean;
  name?: string;
}

interface UIState {
  selected: Record<string, true>;
  selectAllMatching: boolean;
  anchorId: string | null;
  cursorId: string | null;
  page: number;
  composes: ComposeWin[];
  toast: Toast | null;
  notices: Notice[];
  navOpen: boolean;
  quickSettings: boolean;
  shortcutsHelp: boolean;
  viewer: { attachments: Attachment[]; index: number } | null;
  dragIds: string[] | null;
  searchFocused: boolean;
  labelDialog: LabelDialogState | null;
  signedOut: boolean;

  setSelected: (ids: string[], on: boolean) => void;
  toggleSelected: (id: string) => void;
  clearSelection: () => void;
  setSelectAllMatching: (v: boolean) => void;
  setAnchor: (id: string | null) => void;
  setCursor: (id: string | null) => void;
  setPage: (p: number) => void;
  openCompose: (draftId: string) => void;
  closeCompose: (id: string) => void;
  closeComposeForDraft: (draftId: string) => void;
  patchCompose: (id: string, patch: Partial<ComposeWin>) => void;
  showToast: (message: string, actions?: ToastAction[], duration?: number) => void;
  dismissToast: (id?: string) => void;
  pushNotice: (n: Omit<Notice, 'id'>) => void;
  dismissNotice: (id: string) => void;
  set: (patch: Partial<UIState>) => void;
}

export const useUI = create<UIState>()((set, get) => ({
  selected: {},
  selectAllMatching: false,
  anchorId: null,
  cursorId: null,
  page: 0,
  composes: [],
  toast: null,
  notices: [],
  navOpen: false,
  quickSettings: false,
  shortcutsHelp: false,
  viewer: null,
  dragIds: null,
  searchFocused: false,
  labelDialog: null,
  signedOut: false,

  setSelected: (ids, on) => {
    const selected = { ...get().selected };
    for (const id of ids) {
      if (on) selected[id] = true;
      else delete selected[id];
    }
    set({ selected, selectAllMatching: on ? get().selectAllMatching : false });
  },
  toggleSelected: (id) => get().setSelected([id], !get().selected[id]),
  clearSelection: () => set({ selected: {}, selectAllMatching: false, anchorId: null }),
  setSelectAllMatching: (v) => set({ selectAllMatching: v }),
  setAnchor: (id) => set({ anchorId: id }),
  setCursor: (id) => set({ cursorId: id }),
  setPage: (p) => set({ page: p }),

  openCompose: (draftId) => {
    const existing = get().composes.find((c) => c.draftId === draftId);
    if (existing) {
      set({ composes: get().composes.map((c) => (c.id === existing.id ? { ...c, minimized: false } : c)) });
      return;
    }
    // Gmail keeps at most a handful of windows docked; the oldest collapses first.
    const composes = get().composes.map((c, i, arr) => (arr.length >= 2 && i < arr.length - 1 ? { ...c, minimized: true } : c));
    set({ composes: [...composes, { id: uid('cw'), draftId, minimized: false, maximized: false }].slice(-4) });
  },
  closeCompose: (id) => set({ composes: get().composes.filter((c) => c.id !== id) }),
  closeComposeForDraft: (draftId) => set({ composes: get().composes.filter((c) => c.draftId !== draftId) }),
  patchCompose: (id, patch) => set({ composes: get().composes.map((c) => (c.id === id ? { ...c, ...patch } : c)) }),

  showToast: (message, actions, duration = 6000) => set({ toast: { id: uid('toast'), message, actions, duration } }),
  dismissToast: (id) => {
    if (!id || get().toast?.id === id) set({ toast: null });
  },
  pushNotice: (n) => set({ notices: [...get().notices, { ...n, id: uid('n') }].slice(-3) }),
  dismissNotice: (id) => set({ notices: get().notices.filter((n) => n.id !== id) }),
  set: (patch) => set(patch),
}));

import type { Category, Contact, Draft, Label, Thread } from '../data/types';
import { CONTACTS, ME } from '../data/seed';
import { firstName } from '../lib/format';
import type { Route, SystemFolder } from '../lib/router';
import { parseQuery, threadMatches } from '../lib/search';
import type { MailState } from './mail';

export type Row = { kind: 'thread'; id: string; thread: Thread } | { kind: 'draft'; id: string; draft: Draft };

export function lastDate(t: Thread): number {
  return t.messages[t.messages.length - 1]?.date ?? 0;
}

export function isSnoozed(t: Thread, now: number) {
  return !!t.snoozedUntil && t.snoozedUntil > now;
}

export function isSentByMe(t: Thread) {
  return t.messages.some((m) => m.from.email === ME.email);
}

export function inFolder(t: Thread, folder: SystemFolder, now: number, category?: Category | null): boolean {
  const live = !t.trashed && !t.spam;
  switch (folder) {
    case 'inbox':
      return live && t.inInbox && !isSnoozed(t, now) && (!category || t.category === category);
    case 'starred':
      return live && t.starred;
    case 'snoozed':
      return live && isSnoozed(t, now);
    case 'important':
      return live && t.important;
    case 'sent':
      return live && isSentByMe(t);
    case 'all':
      return live;
    case 'spam':
      return t.spam && !t.trashed;
    case 'trash':
      return t.trashed;
    default:
      return false;
  }
}

function byDateDesc(a: Thread, b: Thread) {
  return lastDate(b) - lastDate(a);
}

export function visibleDrafts(drafts: Record<string, Draft>): Draft[] {
  return Object.values(drafts)
    .filter((d) => !d.scheduledAt && !d.outgoing)
    .sort((a, b) => b.updatedAt - a.updatedAt);
}

export function scheduledDrafts(drafts: Record<string, Draft>): Draft[] {
  return Object.values(drafts)
    .filter((d) => d.scheduledAt && !d.outgoing)
    .sort((a, b) => (a.scheduledAt ?? 0) - (b.scheduledAt ?? 0));
}

export function rowsForRoute(s: Pick<MailState, 'threads' | 'drafts' | 'labels' | 'settings'>, route: Route, now: number): Row[] {
  if (route.view === 'settings') return [];
  const all = Object.values(s.threads);
  let threads: Thread[];
  if (route.view === 'folder') {
    if (route.folder === 'drafts') return visibleDrafts(s.drafts).map((d) => ({ kind: 'draft', id: d.id, draft: d }));
    if (route.folder === 'scheduled') return scheduledDrafts(s.drafts).map((d) => ({ kind: 'draft', id: d.id, draft: d }));
    const category = route.folder === 'inbox' && s.settings.categories ? route.category ?? 'primary' : null;
    threads = all.filter((t) => inFolder(t, route.folder, now, category));
    if (route.folder === 'snoozed') threads.sort((a, b) => (a.snoozedUntil ?? 0) - (b.snoozedUntil ?? 0));
    else threads.sort(byDateDesc);
    if (route.folder === 'inbox' && s.settings.inboxSort !== 'default') {
      const key = s.settings.inboxSort === 'unreadFirst' ? (t: Thread) => (t.unread ? 0 : 1) : (t: Thread) => (t.starred ? 0 : 1);
      threads.sort((a, b) => key(a) - key(b) || byDateDesc(a, b));
    }
  } else if (route.view === 'label') {
    threads = all.filter((t) => !t.trashed && !t.spam && t.labels.includes(route.labelId)).sort(byDateDesc);
  } else {
    const pq = parseQuery(route.query, now);
    threads = all.filter((t) => threadMatches(t, pq, { labels: s.labels, meEmail: ME.email, now })).sort(byDateDesc);
  }
  return threads.map((t) => ({ kind: 'thread', id: t.id, thread: t }));
}

export interface Counts {
  inbox: number;
  categories: Record<Category, number>;
  drafts: number;
  scheduled: number;
  spam: number;
  snoozed: number;
  labels: Record<string, number>;
}

export function computeCounts(s: Pick<MailState, 'threads' | 'drafts' | 'settings'>, now: number): Counts {
  const counts: Counts = {
    inbox: 0,
    categories: { primary: 0, promotions: 0, social: 0, updates: 0 },
    drafts: visibleDrafts(s.drafts).length,
    scheduled: scheduledDrafts(s.drafts).length,
    spam: 0,
    snoozed: 0,
    labels: {},
  };
  for (const t of Object.values(s.threads)) {
    if (t.spam && t.unread && !t.trashed) counts.spam++;
    if (isSnoozed(t, now) && !t.trashed) counts.snoozed++;
    if (!t.unread || t.trashed || t.spam) continue;
    if (inFolder(t, 'inbox', now)) {
      counts.categories[t.category]++;
      if (!s.settings.categories || t.category === 'primary') counts.inbox++;
    }
    for (const l of t.labels) counts.labels[l] = (counts.labels[l] ?? 0) + 1;
  }
  return counts;
}

/** "Maya, me, Devon" style participant summary for list rows. */
export function participants(t: Thread, meEmail = ME.email): { names: { label: string; unread: boolean }[]; count: number } {
  const seen = new Map<string, { label: string; unread: boolean }>();
  const multi = new Set(t.messages.map((m) => m.from.email)).size > 1;
  t.messages.forEach((m, i) => {
    const isMe = m.from.email === meEmail;
    const label = isMe ? 'me' : multi ? firstName(m.from) : m.from.name || m.from.email;
    const unread = t.unread && i === t.messages.length - 1;
    const prev = seen.get(m.from.email);
    seen.delete(m.from.email);
    seen.set(m.from.email, { label, unread: unread || !!prev?.unread });
  });
  let names = Array.from(seen.values());
  if (names.length > 3) names = [names[0], { label: '…', unread: false }, ...names.slice(-2)];
  return { names, count: t.messages.length };
}

export function labelMap(labels: Label[]): Record<string, Label> {
  return Object.fromEntries(labels.map((l) => [l.id, l]));
}

/** All addresses the user has corresponded with, ranked by how often they appear. */
export function knownContacts(threads: Record<string, Thread>): Contact[] {
  const score = new Map<string, { c: Contact; n: number }>();
  const byEmail = new Map(Object.values(CONTACTS).map((c) => [c.email.toLowerCase(), c]));
  const bump = (c: Contact, n: number) => {
    const key = c.email.toLowerCase();
    if (key === ME.email) return;
    const cur = score.get(key);
    if (cur) cur.n += n;
    else score.set(key, { c: byEmail.get(key) ?? c, n });
  };
  for (const c of Object.values(CONTACTS)) bump(c, c.kind === 'brand' ? 0 : 1);
  for (const t of Object.values(threads)) {
    for (const m of t.messages) {
      if (m.from.email === ME.email) for (const c of [...m.to, ...m.cc]) bump(c, 4);
      else bump(m.from, 1);
    }
  }
  return Array.from(score.values())
    .sort((a, b) => b.n - a.n)
    .map((x) => x.c);
}

export function folderTitle(route: Route, labels: Label[]): string {
  if (route.view === 'label') return labels.find((l) => l.id === route.labelId)?.name ?? 'Label';
  if (route.view === 'search') return 'Search results';
  if (route.view === 'settings') return 'Settings';
  return FOLDER_NAMES[route.folder];
}

export const FOLDER_NAMES: Record<SystemFolder, string> = {
  inbox: 'Inbox',
  starred: 'Starred',
  snoozed: 'Snoozed',
  important: 'Important',
  sent: 'Sent',
  scheduled: 'Scheduled',
  drafts: 'Drafts',
  all: 'All Mail',
  spam: 'Spam',
  trash: 'Trash',
};

import { useSyncExternalStore } from 'react';
import type { Category } from '../data/types';

export const SYSTEM_FOLDERS = [
  'inbox', 'starred', 'snoozed', 'important', 'sent', 'scheduled', 'drafts', 'all', 'spam', 'trash',
] as const;
export type SystemFolder = (typeof SYSTEM_FOLDERS)[number];

export type Route =
  | { view: 'folder'; folder: SystemFolder; category?: Category; threadId?: string }
  | { view: 'label'; labelId: string; threadId?: string }
  | { view: 'search'; query: string; threadId?: string }
  | { view: 'settings'; tab: string };

const CATEGORIES: Category[] = ['primary', 'promotions', 'social', 'updates'];

export function parseHash(hash: string): Route {
  const parts = hash.replace(/^#\/?/, '').split('/').filter(Boolean).map((p) => decodeURIComponent(p));
  const [head, a, b] = parts;
  if (!head) return { view: 'folder', folder: 'inbox' };
  if (head === 'category' && a && CATEGORIES.includes(a as Category)) {
    return { view: 'folder', folder: 'inbox', category: a as Category, threadId: b };
  }
  if (head === 'label' && a) return { view: 'label', labelId: a, threadId: b };
  if (head === 'search') return { view: 'search', query: a ?? '', threadId: b };
  if (head === 'settings') return { view: 'settings', tab: a ?? 'general' };
  if ((SYSTEM_FOLDERS as readonly string[]).includes(head)) {
    return { view: 'folder', folder: head as SystemFolder, threadId: a };
  }
  return { view: 'folder', folder: 'inbox' };
}

export function routeToHash(r: Route): string {
  const enc = encodeURIComponent;
  switch (r.view) {
    case 'folder': {
      const base = r.folder === 'inbox' && r.category && r.category !== 'primary' ? `category/${r.category}` : r.folder;
      return `#${base}${r.threadId ? `/${enc(r.threadId)}` : ''}`;
    }
    case 'label':
      return `#label/${enc(r.labelId)}${r.threadId ? `/${enc(r.threadId)}` : ''}`;
    case 'search':
      return `#search/${enc(r.query)}${r.threadId ? `/${enc(r.threadId)}` : ''}`;
    case 'settings':
      return `#settings/${enc(r.tab)}`;
  }
}

/** Route without the open conversation — i.e. the list the conversation belongs to. */
export function listRoute(r: Route): Route {
  if (r.view === 'settings') return { view: 'folder', folder: 'inbox' };
  return { ...r, threadId: undefined } as Route;
}

export function withThread(r: Route, threadId: string | undefined): Route {
  if (r.view === 'settings') return { view: 'folder', folder: 'inbox', threadId };
  return { ...r, threadId } as Route;
}

export function routeKey(r: Route): string {
  return routeToHash(listRoute(r));
}

export function navigate(r: Route | string, replace = false) {
  const hash = typeof r === 'string' ? r : routeToHash(r);
  if (hash === window.location.hash) return;
  if (replace) {
    history.replaceState(null, '', hash);
    window.dispatchEvent(new HashChangeEvent('hashchange'));
  } else {
    window.location.hash = hash;
  }
}

function subscribe(cb: () => void) {
  window.addEventListener('hashchange', cb);
  return () => window.removeEventListener('hashchange', cb);
}

let cachedHash = '';
let cachedRoute: Route = { view: 'folder', folder: 'inbox' };

function getSnapshot(): Route {
  const h = window.location.hash;
  if (h !== cachedHash) {
    cachedHash = h;
    cachedRoute = parseHash(h);
  }
  return cachedRoute;
}

export function useRoute(): Route {
  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

export function getRoute(): Route {
  return getSnapshot();
}

import type { AttachmentKind, Contact } from '../data/types';

const MIN = 60_000;
const HOUR = 60 * MIN;
const DAY = 24 * HOUR;

export const TIME = { MIN, HOUR, DAY };

export function uid(prefix = 'id'): string {
  return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function sameDay(a: Date, b: Date) {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

/** Gmail list-style date: "3:42 PM" today, "Sep 12" this year, "9/12/25" otherwise. */
export function listDate(ts: number, now = Date.now()): string {
  const d = new Date(ts);
  const n = new Date(now);
  if (sameDay(d, n)) return d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
  if (d.getFullYear() === n.getFullYear()) return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  return d.toLocaleDateString('en-US', { month: 'numeric', day: 'numeric', year: '2-digit' });
}

export function fullDate(ts: number): string {
  const d = new Date(ts);
  return d.toLocaleString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });
}

export function relative(ts: number, now = Date.now()): string {
  const diff = now - ts;
  const future = diff < 0;
  const abs = Math.abs(diff);
  let out: string;
  if (abs < MIN) out = 'just now';
  else if (abs < HOUR) {
    const m = Math.round(abs / MIN);
    out = `${m} minute${m === 1 ? '' : 's'}`;
  } else if (abs < DAY) {
    const h = Math.round(abs / HOUR);
    out = `${h} hour${h === 1 ? '' : 's'}`;
  } else if (abs < 30 * DAY) {
    const d = Math.round(abs / DAY);
    out = `${d} day${d === 1 ? '' : 's'}`;
  } else {
    const mo = Math.round(abs / (30 * DAY));
    if (mo < 12) out = `${mo} month${mo === 1 ? '' : 's'}`;
    else {
      const y = Math.round(abs / (365 * DAY));
      out = `${y} year${y === 1 ? '' : 's'}`;
    }
  }
  if (out === 'just now') return out;
  return future ? `in ${out}` : `${out} ago`;
}

/** "Sep 12, 2026, 3:42 PM (2 days ago)" */
export function messageDate(ts: number, now = Date.now()): string {
  const d = new Date(ts);
  const base = d.toLocaleString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });
  return `${base} (${relative(ts, now)})`;
}

export function scheduleLabel(ts: number, now = Date.now()): string {
  const d = new Date(ts);
  const n = new Date(now);
  const tomorrow = new Date(now + DAY);
  const time = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
  if (sameDay(d, n)) return `Today, ${time}`;
  if (sameDay(d, tomorrow)) return `Tomorrow, ${time}`;
  return `${d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}, ${time}`;
}

export function fileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1).replace(/\.0$/, '')} MB`;
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`;
}

export function kindFromName(name: string, mime = ''): AttachmentKind {
  const ext = name.split('.').pop()?.toLowerCase() ?? '';
  if (mime.startsWith('image/') || ['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg', 'heic'].includes(ext)) return 'image';
  if (ext === 'pdf') return 'pdf';
  if (['doc', 'docx', 'txt', 'md', 'rtf', 'pages'].includes(ext)) return 'doc';
  if (['xls', 'xlsx', 'csv', 'numbers'].includes(ext)) return 'sheet';
  if (['ppt', 'pptx', 'key'].includes(ext)) return 'slides';
  if (['zip', 'rar', '7z', 'tar', 'gz'].includes(ext)) return 'zip';
  if (mime.startsWith('audio/') || ['mp3', 'm4a', 'wav', 'aac'].includes(ext)) return 'audio';
  if (mime.startsWith('video/') || ['mp4', 'mov', 'webm'].includes(ext)) return 'video';
  return 'file';
}

const AVATAR_COLORS = [
  '#1a73e8', '#d93025', '#188038', '#e37400', '#a142f4', '#007b83', '#c5221f', '#b06000',
  '#1e8e3e', '#9334e6', '#d01884', '#129eaf', '#5f6368', '#3c4043', '#8430ce', '#185abc',
];

export function hash(str: string): number {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

export function avatarColor(c: Pick<Contact, 'email' | 'color'>): string {
  return c.color ?? AVATAR_COLORS[hash(c.email) % AVATAR_COLORS.length];
}

export function initials(c: Pick<Contact, 'name' | 'email'>): string {
  const src = (c.name || c.email).trim();
  return (src[0] ?? '?').toUpperCase();
}

export function firstName(c: Pick<Contact, 'name' | 'email'>): string {
  const n = c.name?.trim();
  if (!n) return c.email.split('@')[0];
  return n.split(/\s+/)[0];
}

export function displayName(c: Pick<Contact, 'name' | 'email'>): string {
  return c.name?.trim() || c.email;
}

export function escapeHtml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

const URL_RE = /\b(https?:\/\/[^\s<]+[^\s<.,;:!?)\]'"])/g;

/** Converts seeded plain text (paragraphs, "- " bullets, URLs) to safe HTML. */
export function textToHtml(text: string): string {
  const blocks = text.trim().split(/\n{2,}/);
  return blocks
    .map((block) => {
      const lines = block.split('\n');
      if (lines.every((l) => /^\s*[-•]\s+/.test(l))) {
        return `<ul>${lines.map((l) => `<li>${linkify(escapeHtml(l.replace(/^\s*[-•]\s+/, '')))}</li>`).join('')}</ul>`;
      }
      if (lines.every((l) => /^\s*\d+[.)]\s+/.test(l))) {
        return `<ol>${lines.map((l) => `<li>${linkify(escapeHtml(l.replace(/^\s*\d+[.)]\s+/, '')))}</li>`).join('')}</ol>`;
      }
      return `<p>${lines.map((l) => linkify(escapeHtml(l))).join('<br>')}</p>`;
    })
    .join('');
}

function linkify(s: string): string {
  return s.replace(URL_RE, (url) => `<a href="${url}" target="_blank" rel="noopener noreferrer">${url}</a>`);
}

/** Collapses HTML into readable plain text (used for snippets and search). */
export function htmlToText(html: string): string {
  if (typeof DOMParser === 'undefined') {
    return html.replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
  }
  const doc = new DOMParser().parseFromString(`<body>${html}</body>`, 'text/html');
  doc.querySelectorAll('style,script').forEach((n) => n.remove());
  doc.querySelectorAll('br').forEach((n) => n.replaceWith('\n'));
  doc.querySelectorAll('p,div,li,tr,h1,h2,h3,h4,table').forEach((n) => n.append('\n'));
  return (doc.body.textContent ?? '').replace(/[ \t ]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
}

export function snippetOf(text: string, len = 180): string {
  const s = text.replace(/\s+/g, ' ').trim();
  return s.length > len ? `${s.slice(0, len)}…` : s;
}

export function pluralize(n: number, one: string, many = `${one}s`): string {
  return `${n} ${n === 1 ? one : many}`;
}

export function clamp(n: number, min: number, max: number) {
  return Math.max(min, Math.min(max, n));
}

export function isValidEmail(s: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.trim());
}

/** Parses "Name <email>" or bare email strings typed in the recipient field. */
export function parseAddress(raw: string): Contact | null {
  const s = raw.trim().replace(/[,;]+$/, '');
  if (!s) return null;
  const m = s.match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/);
  if (m) {
    const email = m[2].trim();
    return isValidEmail(email) ? { name: m[1].trim(), email } : null;
  }
  return isValidEmail(s) ? { name: '', email: s } : null;
}

const ALLOWED_TAGS = new Set([
  'p', 'br', 'div', 'span', 'b', 'strong', 'i', 'em', 'u', 's', 'strike', 'ul', 'ol', 'li', 'a', 'blockquote',
  'h1', 'h2', 'h3', 'pre', 'code', 'font', 'hr', 'sub', 'sup',
]);

const ALLOWED_STYLE = new Set([
  'color', 'background-color', 'font-size', 'font-weight', 'font-style', 'text-decoration', 'text-align', 'font-family',
]);

function cleanStyle(style: string): string {
  return style
    .split(';')
    .map((decl) => decl.trim())
    .filter((decl) => {
      const [prop, ...rest] = decl.split(':');
      const value = rest.join(':').toLowerCase();
      return prop && ALLOWED_STYLE.has(prop.trim().toLowerCase()) && !value.includes('url(') && !value.includes('expression');
    })
    .join('; ');
}

/** Whitelist sanitiser for HTML produced by the compose editor or pasted by the user. */
export function sanitizeHtml(html: string): string {
  if (typeof DOMParser === 'undefined') return html.replace(/<[^>]+>/g, '');
  const doc = new DOMParser().parseFromString(`<body>${html}</body>`, 'text/html');
  const walk = (node: Element) => {
    for (const child of Array.from(node.children)) {
      const tag = child.tagName.toLowerCase();
      if (!ALLOWED_TAGS.has(tag)) {
        if (['script', 'style', 'iframe', 'object', 'embed', 'meta', 'link', 'title'].includes(tag)) {
          child.remove();
          continue;
        }
        // Unwrap unknown elements but keep their text content.
        walk(child);
        child.replaceWith(...Array.from(child.childNodes));
        continue;
      }
      for (const attr of Array.from(child.attributes)) {
        const name = attr.name.toLowerCase();
        if (tag === 'a' && name === 'href') {
          if (!/^(https?:|mailto:)/i.test(attr.value.trim())) child.removeAttribute('href');
          continue;
        }
        if (tag === 'font' && ['color', 'size', 'face'].includes(name)) continue;
        if (name === 'style') {
          const cleaned = cleanStyle(attr.value);
          if (cleaned) child.setAttribute('style', cleaned);
          else child.removeAttribute('style');
          continue;
        }
        child.removeAttribute(attr.name);
      }
      if (tag === 'a') {
        child.setAttribute('target', '_blank');
        child.setAttribute('rel', 'noopener noreferrer');
      }
      walk(child);
    }
  };
  walk(doc.body);
  return doc.body.innerHTML;
}

import { useEffect, useRef, useState, useSyncExternalStore } from 'react';

export function useMediaQuery(query: string): boolean {
  return useSyncExternalStore(
    (cb) => {
      const mql = window.matchMedia(query);
      mql.addEventListener('change', cb);
      return () => mql.removeEventListener('change', cb);
    },
    () => window.matchMedia(query).matches,
    () => false,
  );
}

export const MOBILE_QUERY = '(max-width: 720px)';
export const TABLET_QUERY = '(max-width: 1100px)';

export function useIsMobile() {
  return useMediaQuery(MOBILE_QUERY);
}

/** Re-renders periodically so relative times and snooze states stay fresh. */
export function useNow(intervalMs = 30_000): number {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const id = window.setInterval(() => setNow(Date.now()), intervalMs);
    return () => window.clearInterval(id);
  }, [intervalMs]);
  return now;
}

export function useOutsideClick<T extends HTMLElement>(onOutside: () => void, active = true) {
  const ref = useRef<T>(null);
  const cb = useRef(onOutside);
  cb.current = onOutside;
  useEffect(() => {
    if (!active) return;
    const handler = (e: PointerEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) cb.current();
    };
    document.addEventListener('pointerdown', handler, true);
    return () => document.removeEventListener('pointerdown', handler, true);
  }, [active]);
  return ref;
}

export function useDebouncedCallback<A extends unknown[]>(fn: (...args: A) => void, ms: number) {
  const timer = useRef<number | undefined>(undefined);
  const latest = useRef(fn);
  latest.current = fn;
  useEffect(() => () => window.clearTimeout(timer.current), []);
  return (...args: A) => {
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => latest.current(...args), ms);
  };
}

