function ReplyModeMenu({ icon: Icon, onMode, onPopOut }: { icon: IconType; onMode: (m: 'reply' | 'replyAll' | 'forward') => void; onPopOut: () => void }) {
  const m = useAnchor<HTMLButtonElement>();
