+      const field = d.to.includes(bad) ? 'To' : d.cc.includes(bad) ? 'Cc' : 'Bcc';
+      setModal({ title: 'Error', body: `The address “${bad.email}” in the “${field}” field was not recognized. Please make sure that all addresses are properly formed.` });
+      return false;
+    }
+    return true;
+  };
+
+  const needsConfirm = () => {
