+        <label className="field">
+          <span>Web address or email</span>
+          <input value={url} onChange={(e) => setUrl(e.target.value)} placeholder="https://" autoFocus />
+        </label>
+        <button type="submit" hidden />
+      </form>
+    </Dialog>
+  );
+}

