        <button type="button" className="signed-out-account" onClick={() => useUI.getState().set({ signedOut: false })}>
          <Avatar contact={me} size={36} />
          <span>
            <b>{me.name}</b>
            <span>{me.email}</span>
          </span>
          <span className="signed-out-cta">Sign in</span>
