            date: now,
            html,
            text: htmlToText(html),
            attachments: d.attachments,
            quoted: d.quoted,
          };
          const toMe = [...d.to, ...d.cc, ...d.bcc].some((c) => c.email.toLowerCase() === ME.email);
          if (existing) {
            threads[threadId] = {
              ...existing,
              messages: [...existing.messages, message],
              unread: toMe,
              inInbox: existing.inInbox || toMe,
              trashed: false,
              spam: false,
            };
          } else {
            threads[threadId] = {
              id: threadId,
              subject: d.subject.trim() || '(no subject)',
              messages: [message],
              category: 'primary',
              labels: [],
              unread: toMe,
              starred: false,
              important: false,
              inInbox: toMe,
              trashed: false,
              spam: false,
              snoozedUntil: null,
