          data-tip={p.label}
          style={{ color: p.color }}
          onClick={() => update({ sidePanel: panel === p.id ? null : p.id })}
        >
          <p.icon aria-hidden />
          {p.id === 'tasks' && openTasks > 0 && <span className="rail-badge">{openTasks}</span>}
        </button>
      ))}
      <span className="rail-sep" />
    </nav>
  );
}

export function SidePanel() {
  const panel = useMail((s) => s.settings.sidePanel);
  const update = useMail((s) => s.updateSettings);
  const mobile = useIsMobile();
  if (!panel) return null;
  const def = PANELS.find((p) => p.id === panel)!;
  return (
    <aside className={`side-panel ${mobile ? 'is-mobile' : ''}`} aria-label={def.label}>
      <div className="sp-head">
        <h2>{def.label}</h2>
        <IconButton icon={MdClose} label={`Close ${def.label}`} onClick={() => update({ sidePanel: null })} />
      </div>
      <div className="sp-body">
        {panel === 'calendar' && <CalendarPanel />}
        {panel === 'tasks' && <TasksPanel />}
        {panel === 'contacts' && <ContactsPanel />}
      </div>
    </aside>
  );
}

/* ---------------- Calendar ---------------- */

const START_HOUR = 7;
const END_HOUR = 21;
const HOUR_PX = 48;

function startOfDay(ts: number) {
  const d = new Date(ts);
  d.setHours(0, 0, 0, 0);
  return d.getTime();
}

function CalendarPanel() {
  const events = useMail((s) => s.events);
  const now = useNow(60_000);
  const [day, setDay] = useState(() => startOfDay(Date.now()));
  const [draft, setDraft] = useState<{ start: number } | null>(null);
  const gridRef = useRef<HTMLDivElement>(null);
  const isToday = day === startOfDay(now);
  const dayEvents = events.filter((e) => e.start >= day && e.start < day + TIME.DAY).sort((a, b) => a.start - b.start);

  useEffect(() => {
    const h = isToday ? new Date(now).getHours() : 9;
    gridRef.current?.scrollTo({ top: Math.max(0, (h - START_HOUR - 1) * HOUR_PX) });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [day]);

  const label = new Date(day).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
  const nowTop = ((now - day) / TIME.HOUR - START_HOUR) * HOUR_PX;

  return (
    <div className="cal">
      <div className="cal-nav">
        <button type="button" className="btn btn-outline btn-sm" onClick={() => setDay(startOfDay(Date.now()))} disabled={isToday}>Today</button>
        <IconButton icon={MdChevronLeft} label="Previous day" onClick={() => setDay(day - TIME.DAY)} />
        <IconButton icon={MdChevronRight} label="Next day" onClick={() => setDay(day + TIME.DAY)} />
        <span className="cal-date">{label}</span>
      </div>
      <div className="cal-grid" ref={gridRef}>
        <div className="cal-hours" style={{ height: (END_HOUR - START_HOUR) * HOUR_PX }}>
          {Array.from({ length: END_HOUR - START_HOUR }, (_, i) => {
            const h = START_HOUR + i;
            return (
              <button
                key={h}
                type="button"
                className="cal-hour"
                style={{ top: i * HOUR_PX, height: HOUR_PX }}
                aria-label={`Create event at ${h}:00`}
                onClick={() => setDraft({ start: day + h * TIME.HOUR })}
              >
                <span className="cal-hour-label">{new Date(day + h * TIME.HOUR).toLocaleTimeString('en-US', { hour: 'numeric' })}</span>
              </button>
            );
          })}
          {dayEvents.map((e) => {
            const top = ((e.start - day) / TIME.HOUR - START_HOUR) * HOUR_PX;
            const height = Math.max(22, ((e.end - e.start) / TIME.HOUR) * HOUR_PX - 2);
            const past = e.end < now;
            return (
              <div key={e.id} className={`cal-event ${past ? 'is-past' : ''}`} style={{ top, height, background: e.color }} title={e.title}>
                <div className="cal-event-title">{e.title}</div>
                {height > 34 && (
                  <div className="cal-event-meta">
                    {fmtTime(e.start)} – {fmtTime(e.end)}
                    {e.location && height > 50 && <><br /><MdPlace aria-hidden /> {e.location}</>}
                  </div>
                )}
                <button
                  type="button"
                  className="cal-event-x"
                  aria-label={`Delete ${e.title}`}
                  onClick={() => {
                    useMail.getState().deleteEvent(e.id);
                    useUI.getState().showToast('Event deleted.', [{ label: 'Undo', run: () => useMail.getState().addEvent(e) }]);
                  }}
                >
                  <MdClose aria-hidden />
                </button>
              </div>
            );
          })}
          {isToday && nowTop >= 0 && nowTop <= (END_HOUR - START_HOUR) * HOUR_PX && <div className="cal-now" style={{ top: nowTop }} aria-hidden />}
        </div>
      </div>
      <button type="button" className="btn btn-tonal cal-add" onClick={() => setDraft({ start: day + (isToday ? Math.min(END_HOUR - 1, new Date(now).getHours() + 1) : 10) * TIME.HOUR })}>
        <MdAdd aria-hidden /> Create event
      </button>
      <EventDialog draft={draft} onClose={() => setDraft(null)} />
    </div>
  );
}

function fmtTime(ts: number) {
  return new Date(ts).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
}

const EVENT_COLORS = ['#039be5', '#33b679', '#e67c73', '#f6bf26', '#8e24aa', '#f4511e'];

function EventDialog({ draft, onClose }: { draft: { start: number } | null; onClose: () => void }) {
  const [title, setTitle] = useState('');
  const [time, setTime] = useState('10:00');
  const [duration, setDuration] = useState(60);
  const [location, setLocation] = useState('');
  const [color, setColor] = useState(EVENT_COLORS[0]);
  useEffect(() => {
    if (!draft) return;
    const d = new Date(draft.start);
    setTitle('');
    setLocation('');
    setDuration(60);
    setTime(`${String(d.getHours()).padStart(2, '0')}:00`);
  }, [draft]);
  if (!draft) return null;
  const save = () => {
    if (!title.trim()) return;
    const [h, m] = time.split(':').map(Number);
    const start = startOfDay(draft.start) + h * TIME.HOUR + m * TIME.MIN;
    useMail.getState().addEvent({ title: title.trim(), start, end: start + duration * TIME.MIN, location: location.trim() || undefined, color });
    useUI.getState().showToast(`“${title.trim()}” added to your calendar.`);
    onClose();
  };
  return (
    <Dialog
      open
      onClose={onClose}
      title="New event"
      actions={
        <>
          <button type="button" className="btn btn-text" onClick={onClose}>Cancel</button>
          <button type="button" className="btn btn-primary" disabled={!title.trim()} onClick={save}>Save</button>
        </>
      }
    >
      <form className="form-stack" onSubmit={(e) => { e.preventDefault(); save(); }}>
        <label className="field"><span>Title</span><input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Add title" autoFocus /></label>
        <div className="field-row">
          <label className="field"><span>{new Date(draft.start).toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}</span><input type="time" value={time} onChange={(e) => setTime(e.target.value)} /></label>
          <label className="field">
            <span>Duration</span>
            <select value={duration} onChange={(e) => setDuration(Number(e.target.value))}>
              <option value={15}>15 min</option>
              <option value={30}>30 min</option>
              <option value={45}>45 min</option>
              <option value={60}>1 hour</option>
              <option value={90}>1.5 hours</option>
              <option value={120}>2 hours</option>
            </select>
          </label>
        </div>
        <label className="field"><span>Location</span><input value={location} onChange={(e) => setLocation(e.target.value)} placeholder="Add location" /></label>
        <div className="swatches">
          {EVENT_COLORS.map((c) => (
            <button key={c} type="button" className={`swatch ${c === color ? 'is-on' : ''}`} style={{ background: c }} aria-label={`Color ${c}`} onClick={() => setColor(c)} />
          ))}
        </div>
        <button type="submit" hidden />
      </form>
    </Dialog>
  );
}

/* ---------------- Tasks ---------------- */

function TasksPanel() {
  const tasks = useMail((s) => s.tasks);
  const threads = useMail((s) => s.threads);
  const [title, setTitle] = useState('');
  const [showDone, setShowDone] = useState(false);
  const now = useNow(60_000);
  const open = tasks.filter((t) => !t.done);
  const done = tasks.filter((t) => t.done);
  const add = () => {
    const clean = title.trim();
    if (!clean) return;
    useMail.getState().addTask(clean);
    setTitle('');
  };
  const dueLabel = (due: number) => {
    const d = startOfDay(due);
    const today = startOfDay(now);
    if (d === today) return { text: 'Today', late: due < now };
    if (d === today + TIME.DAY) return { text: 'Tomorrow', late: false };
    if (d < today) return { text: new Date(due).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }), late: true };
    return { text: new Date(due).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' }), late: false };
  };
  const row = (t: (typeof tasks)[number]) => {
    const thread = t.threadId ? threads[t.threadId] : undefined;
    const due = t.due ? dueLabel(t.due) : null;
    return (
      <li key={t.id} className={`task ${t.done ? 'is-done' : ''}`}>
        <button
          type="button"
          className="task-check"
          aria-label={t.done ? 'Mark incomplete' : 'Mark complete'}
          onClick={() => {
            useMail.getState().updateTask(t.id, { done: !t.done });
            if (!t.done) useUI.getState().showToast('1 task completed.', [{ label: 'Undo', run: () => useMail.getState().updateTask(t.id, { done: false }) }]);
          }}
        >
          {t.done ? <MdCheckCircle aria-hidden /> : <MdOutlineCircle aria-hidden />}
        </button>
        <div className="task-main">
          <input
            className="task-title"
            defaultValue={t.title}
            aria-label="Task title"
            onBlur={(e) => {
              const v = e.target.value.trim();
              if (v && v !== t.title) useMail.getState().updateTask(t.id, { title: v });
              if (!v) e.target.value = t.title;
            }}
            onKeyDown={(e) => e.key === 'Enter' && (e.target as HTMLInputElement).blur()}
          />
          <div className="task-meta">
            {due && <span className={`task-due ${due.late && !t.done ? 'is-late' : ''}`}>{due.text}</span>}
            {thread && (
              <button type="button" className="task-link" onClick={() => openThread(thread.id, { view: 'folder', folder: 'all' })}>
                <MdOutlineMail aria-hidden /> <span>{thread.subject}</span>
              </button>
            )}
          </div>
        </div>
        <IconButton icon={MdOutlineDelete} size="sm" label="Delete task" className="task-del" onClick={() => {
          useMail.getState().deleteTask(t.id);
          useUI.getState().showToast('Task deleted.', [{ label: 'Undo', run: () => useMail.setState({ tasks: [t, ...useMail.getState().tasks] }) }]);
        }} />
      </li>
    );
  };
  return (
    <div className="tasks">
      <form className="task-add" onSubmit={(e) => { e.preventDefault(); add(); }}>
        <MdAdd aria-hidden />
        <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Add a task" aria-label="Add a task" />
      </form>
      {open.length === 0 ? (
        <div className="tasks-empty">
          <MdOutlineTaskAlt aria-hidden />
          <p>All tasks complete. Nice work!</p>
        </div>
      ) : (
        <ul className="task-list">{open.map(row)}</ul>
      )}
      {done.length > 0 && (
        <>
          <button type="button" className="tasks-done-toggle" onClick={() => setShowDone(!showDone)}>
            {showDone ? <MdExpandLess aria-hidden /> : <MdExpandMore aria-hidden />} Completed ({done.length})
          </button>
          {showDone && <ul className="task-list">{done.map(row)}</ul>}
        </>
      )}
    </div>
  );
}

/* ---------------- Contacts ---------------- */

function ContactsPanel() {
  const threads = useMail((s) => s.threads);
  const [q, setQ] = useState('');
  const all = useMemo(() => knownContacts(threads).filter((c) => c.kind !== 'brand'), [threads]);
  const list = all.filter((c) => !q || c.name.toLowerCase().includes(q.toLowerCase()) || c.email.toLowerCase().includes(q.toLowerCase())).slice(0, 60);
  return (
    <div className="contacts">
      <label className="contacts-search">
        <MdSearch aria-hidden />
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search contacts" aria-label="Search contacts" />
      </label>
      <div className="contacts-count">{q ? `${list.length} matches` : `Frequently contacted · ${all.length}`}</div>
      <ul className="contact-list">
        {list.map((c) => (
          <li key={c.email} className="contact-row">
            <Avatar contact={c} size={36} />
            <div className="contact-text">
              <div className="contact-name">{displayName(c)}</div>
              <div className="contact-email">{c.org ? `${c.org} · ` : ''}{c.email}</div>
            </div>
            <div className="contact-actions">
              <IconButton icon={MdOutlineMail} size="sm" label={`Email ${displayName(c)}`} onClick={() => composeTo(c)} />
              <IconButton icon={MdSearch} size="sm" label={`Find emails with ${displayName(c)}`} onClick={() => navigate({ view: 'search', query: c.email })} />
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}

args.streamContent:
import { useEffect, useState, type CSSProperties, type ReactNode } from 'react';
import { MdArrowBack, MdCheck, MdOutlineFileDownload, MdOutlineRefresh } from 'react-icons/md';
import { LABEL_PALETTE } from '../data/seed';
import { useIsMobile } from '../hooks';
import { navigate } from '../lib/router';
import { useMail, type Settings as SettingsT } from '../store/mail';
import { useUI } from '../store/ui';
import { TINTS } from './overlays';
import { IconButton, Switch } from './primitives';

const TABS = [
  { id: 'general', label: 'General' },
  { id: 'labels', label: 'Labels' },
  { id: 'inbox', label: 'Inbox' },
  { id: 'themes', label: 'Themes' },
  { id: 'data', label: 'Data & storage' },
];

export function Settings({ tab }: { tab: string }) {
  const mobile = useIsMobile();
  const current = TABS.some((t) => t.id === tab) ? tab : 'general';
  return (
    <section className="settings" aria-label="Settings">
      <div className="settings-head">
        {mobile && <IconButton icon={MdArrowBack} label="Back to Inbox" onClick={() => navigate({ view: 'folder', folder: 'inbox' })} />}
        <h1>Settings</h1>
      </div>
      <div className="settings-tabs" role="tablist">
        {TABS.map((t) => (
          <button
            key={t.id}
            type="button"
            role="tab"
            aria-selected={current === t.id}
            className={`settings-tab ${current === t.id ? 'is-active' : ''}`}
            onClick={() => navigate({ view: 'settings', tab: t.id }, true)}
          >
            {t.label}
          </button>
        ))}
      </div>
      <div className="settings-scroll">
        {current === 'general' && <General />}
        {current === 'labels' && <Labels />}
        {current === 'inbox' && <Inbox />}
        {current === 'themes' && <Themes />}
        {current === 'data' && <Data />}
      </div>
    </section>
  );
}

function Row({ title, hint, children }: { title: string; hint?: string; children: ReactNode }) {
  return (
    <div className="set-row">
      <div className="set-label">
        <div className="set-title">{title}</div>
        {hint && <div className="set-hint">{hint}</div>}
      </div>
      <div className="set-control">{children}</div>
    </div>
  );
}

function useSetting<K extends keyof SettingsT>(key: K): [SettingsT[K], (v: SettingsT[K]) => void] {
  const value = useMail((s) => s.settings[key]);
  const update = useMail((s) => s.updateSettings);
  return [value, (v) => update({ [key]: v } as Partial<SettingsT>)];
}

function Radios<T extends string | number>({ name, value, options, onChange }: { name: string; value: T; options: { value: T; label: string }[]; onChange: (v: T) => void }) {
  return (
    <div className="radios" role="radiogroup">
      {options.map((o) => (
        <label key={String(o.value)} className={`radio ${o.value === value ? 'is-on' : ''}`}>
          <input type="radio" name={name} checked={o.value === value} onChange={() => onChange(o.value)} />
          <span className="qs-radio" aria-hidden />
          {o.label}
        </label>
      ))}
    </div>
  );
}

function General() {
  const [displayName, setDisplayName] = useSetting('displayName');
  const [signature, setSignature] = useSetting('signature');
  const [undo, setUndo] = useSetting('undoSeconds');
  const [pageSize, setPageSize] = useSetting('pageSize');
  const [smartReply, setSmartReply] = useSetting('smartReply');
  const [shortcuts, setShortcuts] = useSetting('shortcuts');
  const [hover, setHover] = useSetting('hoverActions');
  const [advance, setAdvance] = useSetting('autoAdvance');
  const [importance, setImportance] = useSetting('importanceMarkers');
  const [density, setDensity] = useSetting('density');
  const [name, setName] = useState(displayName);
  const [sig, setSig] = useState(signature);
  useEffect(() => setName(displayName), [displayName]);
  useEffect(() => setSig(signature), [signature]);
  const dirty = name !== displayName || sig !== signature;
  return (
    <div className="set-group">
      <Row title="Your name" hint="Shown to people you email.">
        <input className="set-input" value={name} onChange={(e) => setName(e.target.value)} maxLength={60} />
      </Row>
      <Row title="Signature" hint="Appended at the end of new messages and replies.">
        <textarea className="set-textarea" rows={4} value={sig} onChange={(e) => setSig(e.target.value)} />
      </Row>
      {dirty && (
        <div className="set-save">
          <button type="button" className="btn btn-text" onClick={() => { setName(displayName); setSig(signature); }}>Cancel</button>
          <button
            type="button"
            className="btn btn-primary"
            onClick={() => {
              setDisplayName(name.trim() || displayName);
              setSignature(sig);
              useUI.getState().showToast('Your preferences have been saved.');
            }}
          >
            Save changes
          </button>
        </div>
      )}
      <Row title="Undo send" hint="Cancel a message for a few seconds after you press Send.">
        <select className="set-select" value={undo} onChange={(e) => setUndo(Number(e.target.value))}>
          {[0, 5, 10, 20, 30].map((s) => <option key={s} value={s}>{s === 0 ? 'Off' : `${s} seconds`}</option>)}
        </select>
      </Row>
      <Row title="Maximum page size" hint="Conversations shown per page.">
        <select className="set-select" value={pageSize} onChange={(e) => { setPageSize(Number(e.target.value)); useUI.getState().setPage(0); }}>
          {[25, 50, 100].map((n) => <option key={n} value={n}>{n}</option>)}
        </select>
      </Row>
      <Row title="Density">
        <Radios name="density" value={density} onChange={setDensity} options={[{ value: 'default', label: 'Default' }, { value: 'comfortable', label: 'Comfortable' }, { value: 'compact', label: 'Compact' }]} />
      </Row>
      <Row title="Auto-advance" hint="After archiving, deleting or muting a conversation, go to:">
        <Radios name="advance" value={advance} onChange={setAdvance} options={[{ value: 'list', label: 'Back to the list' }, { value: 'newer', label: 'Newer conversation' }, { value: 'older', label: 'Older conversation' }]} />
      </Row>
      <Row title="Smart reply" hint="Suggest short replies when available.">
        <Switch checked={smartReply} onChange={setSmartReply} label="Smart reply" />
      </Row>
      <Row title="Keyboard shortcuts" hint="Press ? anywhere to see the list.">
        <Switch checked={shortcuts} onChange={setShortcuts} label="Keyboard shortcuts" />
      </Row>
      <Row title="Hover actions" hint="Show archive, delete, read and snooze buttons when hovering a row.">
        <Switch checked={hover} onChange={setHover} label="Hover actions" />
      </Row>
      <Row title="Importance markers" hint="Show the importance arrow next to conversations.">
        <Switch checked={importance} onChange={setImportance} label="Importance markers" />
      </Row>
    </div>
  );
}

function Labels() {
  const labels = useMail((s) => s.labels);
  const threads = useMail((s) => s.threads);
  const update = useMail((s) => s.updateLabel);
  const counts: Record<string, number> = {};
  for (const t of Object.values(threads)) if (!t.trashed) for (const l of t.labels) counts[l] = (counts[l] ?? 0) + 1;
  return (
    <div className="set-group">
      <div className="set-labels-head">
        <h2>Labels</h2>
        <button type="button" className="btn btn-tonal" onClick={() => useUI.getState().set({ labelDialog: { mode: 'create' } })}>Create new label</button>
      </div>
      <table className="label-table">
        <thead>
          <tr><th>Name</th><th>Conversations</th><th>Show in label list</th><th>Actions</th></tr>
        </thead>
        <tbody>
          {labels.map((l) => (
            <tr key={l.id}>
              <td>
                <span className="label-swatch" style={{ background: l.color }} />
                <button type="button" className="link-btn" onClick={() => navigate({ view: 'label', labelId: l.id })}>{l.name}</button>
              </td>
              <td>{counts[l.id] ?? 0}</td>
              <td>
                <div className="seg">
                  <button type="button" className={!l.hidden ? 'is-on' : ''} onClick={() => update(l.id, { hidden: false })}>show</button>
                  <button type="button" className={l.hidden ? 'is-on' : ''} onClick={() => update(l.id, { hidden: true })}>hide</button>
                </div>
              </td>
              <td className="label-actions">
                <button type="button" className="link-btn" onClick={() => useUI.getState().set({ labelDialog: { mode: 'edit', labelId: l.id } })}>edit</button>
                <button
                  type="button"
                  className="link-btn is-danger"
                  onClick={() => {
                    if (window.confirm(`Remove the label “${l.name}”? Conversations won’t be deleted.`)) {
                      useMail.getState().deleteLabel(l.id);
                      useUI.getState().showToast(`Label “${l.name}” removed.`);
                    }
                  }}
                >
                  remove
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <p className="set-note">Tip: drag conversations from the list onto a label in the sidebar to move them there.</p>
      <div className="set-palette" aria-hidden>
        {LABEL_PALETTE.map((p) => <span key={p.color} style={{ background: p.color }} />)}
      </div>
    </div>
  );
}

function Inbox() {
  const [categories, setCategories] = useSetting('categories');
  const [sort, setSort] = useSetting('inboxSort');
  const [pane, setPane] = useSetting('readingPane');
  return (
    <div className="set-group">
      <Row title="Inbox type" hint="Categories split your inbox into Primary, Promotions, Social and Updates tabs.">
        <div className="set-stack">
          <label className="qs-switch"><span>Use category tabs</span><Switch checked={categories} onChange={setCategories} label="Category tabs" /></label>
          <Radios
            name="sort"
            value={sort}
            onChange={setSort}
            options={[{ value: 'default', label: 'Newest first' }, { value: 'unreadFirst', label: 'Unread first' }, { value: 'starredFirst', label: 'Starred first' }]}
          />
        </div>
      </Row>
      <Row title="Reading pane" hint="Open conversations next to the list on wide screens.">
        <Radios name="pane" value={pane} onChange={setPane} options={[{ value: 'none', label: 'No split' }, { value: 'right', label: 'Right of inbox' }]} />
      </Row>
    </div>
  );
}

function Themes() {
  const [theme, setTheme] = useSetting('theme');
  const [tint, setTint] = useSetting('tint');
  return (
    <div className="set-group">
      <Row title="Appearance">
        <div className="qs-themes qs-themes-lg">
          {(['light', 'dark', 'system'] as const).map((t) => (
            <button key={t} type="button" className={`qs-theme qs-theme-${t} ${theme === t ? 'is-on' : ''}`} onClick={() => setTheme(t)} aria-pressed={theme === t}>
              <span className="qs-theme-art" aria-hidden />
              <span>{t === 'system' ? 'Device default' : t[0].toUpperCase() + t.slice(1)}</span>
            </button>
          ))}
        </div>
      </Row>
      <Row title="Background" hint="A subtle tint behind the mail list.">
        <div className="tint-cards">
          {TINTS.map((t) => (
            <button key={t.id} type="button" className={`tint-card ${tint === t.id ? 'is-on' : ''}`} onClick={() => setTint(t.id)} style={{ '--tint-l': t.light, '--tint-d': t.dark } as CSSProperties} aria-pressed={tint === t.id}>
              <span className="tint-card-art" aria-hidden>{tint === t.id && <MdCheck />}</span>
              <span>{t.label}</span>
            </button>
          ))}
        </div>
      </Row>
    </div>
  );
}

function Data() {
  const threads = useMail((s) => s.threads);
  const drafts = useMail((s) => s.drafts);
  const reset = useMail((s) => s.resetMailbox);
  const count = Object.keys(threads).length;
  const messages = Object.values(threads).reduce((n, t) => n + t.messages.length, 0);
  let bytes = 0;
  try {
    bytes = (localStorage.getItem('opus-mail') ?? '').length * 2;
  } catch {
    bytes = 0;
  }
  const exportJson = () => {
    const s = useMail.getState();
    const blob = new Blob([JSON.stringify({ threads: s.threads, drafts: s.drafts, labels: s.labels, tasks: s.tasks, events: s.events }, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'mailbox-export.json';
    a.click();
    window.setTimeout(() => URL.revokeObjectURL(url), 2000);
  };
  return (
    <div className="set-group">
      <Row title="Stored on this device" hint="Everything lives in your browser’s local storage. Nothing is sent to a server.">
        <div className="set-stats">
          <div><b>{count}</b><span>conversations</span></div>
          <div><b>{messages}</b><span>messages</span></div>
          <div><b>{Object.keys(drafts).length}</b><span>drafts</span></div>
          <div><b>{(bytes / 1024).toFixed(0)} KB</b><span>used</span></div>
        </div>
      </Row>
      <Row title="Export" hint="Download a JSON copy of your mailbox, labels, tasks and events.">
        <button type="button" className="btn btn-outline" onClick={exportJson}><MdOutlineFileDownload aria-hidden /> Export mailbox</button>
      </Row>
      <Row title="Reset demo mailbox" hint="Restores the original seeded conversations and discards your local changes.">
        <button
          type="button"
          className="btn btn-danger"
          onClick={() => {
            if (window.confirm('Reset the mailbox to its original demo state? Your local changes will be lost.')) {
              reset();
              useUI.getState().clearSelection();
              useUI.getState().set({ composes: [] });
              navigate({ view: 'folder', folder: 'inbox' });
              useUI.getState().showToast('Mailbox reset to demo data.');
            }
          }}
        >
          <MdOutlineRefresh aria-hidden /> Reset mailbox
        </button>
      </Row>
    </div>
  );
}

import { useEffect, useState, type CSSProperties, type ReactNode } from 'react';
import { MdArrowBack, MdCheck, MdOutlineFileDownload, MdOutlineRefresh } from 'react-icons/md';
import { LABEL_PALETTE } from '../data/seed';
import { useIsMobile } from '../hooks';
import { navigate } from '../lib/router';
import { useMail, type Settings as SettingsT } from '../store/mail';
import { useUI } from '../store/ui';
import { TINTS } from './overlays';
import { IconButton, Switch } from './primitives';

const TABS = [
  { id: 'general', label: 'General' },
  { id: 'labels', label: 'Labels' },
  { id: 'inbox', label: 'Inbox' },
  { id: 'themes', label: 'Themes' },
  { id: 'data', label: 'Data & storage' },
];

export function Settings({ tab }: { tab: string }) {
  const mobile = useIsMobile();
  const current = TABS.some((t) => t.id === tab) ? tab : 'general';
  return (
    <section className="settings" aria-label="Settings">
      <div className="settings-head">
        {mobile && <IconButton icon={MdArrowBack} label="Back to Inbox" onClick={() => navigate({ view: 'folder', folder: 'inbox' })} />}
        <h1>Settings</h1>
      </div>
      <div className="settings-tabs" role="tablist">
        {TABS.map((t) => (
          <button
            key={t.id}
            type="button"
            role="tab"
            aria-selected={current === t.id}
            className={`settings-tab ${current === t.id ? 'is-active' : ''}`}
            onClick={() => navigate({ view: 'settings', tab: t.id }, true)}
          >
            {t.label}
          </button>
        ))}
      </div>
      <div className="settings-scroll">
        {current === 'general' && <General />}
        {current === 'labels' && <Labels />}
        {current === 'inbox' && <Inbox />}
        {current === 'themes' && <Themes />}
        {current === 'data' && <Data />}
      </div>
    </section>
  );
}

function Row({ title, hint, children }: { title: string; hint?: string; children: ReactNode }) {
  return (
    <div className="set-row">
      <div className="set-label">
        <div className="set-title">{title}</div>
        {hint && <div className="set-hint">{hint}</div>}
      </div>
      <div className="set-control">{children}</div>
    </div>
  );
}

function useSetting<K extends keyof SettingsT>(key: K): [SettingsT[K], (v: SettingsT[K]) => void] {
  const value = useMail((s) => s.settings[key]);
  const update = useMail((s) => s.updateSettings);
  return [value, (v) => update({ [key]: v } as Partial<SettingsT>)];
}

function Radios<T extends string | number>({ name, value, options, onChange }: { name: string; value: T; options: { value: T; label: string }[]; onChange: (v: T) => void }) {
  return (
    <div className="radios" role="radiogroup">
      {options.map((o) => (
        <label key={String(o.value)} className={`radio ${o.value === value ? 'is-on' : ''}`}>
          <input type="radio" name={name} checked={o.value === value} onChange={() => onChange(o.value)} />
          <span className="qs-radio" aria-hidden />
          {o.label}
        </label>
      ))}
    </div>
  );
}

function General() {
  const [displayName, setDisplayName] = useSetting('displayName');
  const [signature, setSignature] = useSetting('signature');
  const [undo, setUndo] = useSetting('undoSeconds');
  const [pageSize, setPageSize] = useSetting('pageSize');
  const [smartReply, setSmartReply] = useSetting('smartReply');
  const [shortcuts, setShortcuts] = useSetting('shortcuts');
  const [hover, setHover] = useSetting('hoverActions');
  const [advance, setAdvance] = useSetting('autoAdvance');
  const [importance, setImportance] = useSetting('importanceMarkers');
  const [density, setDensity] = useSetting('density');
  const [name, setName] = useState(displayName);
  const [sig, setSig] = useState(signature);
  useEffect(() => setName(displayName), [displayName]);
  useEffect(() => setSig(signature), [signature]);
  const dirty = name !== displayName || sig !== signature;
  return (
    <div className="set-group">
      <Row title="Your name" hint="Shown to people you email.">
        <input className="set-input" value={name} onChange={(e) => setName(e.target.value)} maxLength={60} />
      </Row>
      <Row title="Signature" hint="Appended at the end of new messages and replies.">
        <textarea className="set-textarea" rows={4} value={sig} onChange={(e) => setSig(e.target.value)} />
      </Row>
      {dirty && (
        <div className="set-save">
          <button type="button" className="btn btn-text" onClick={() => { setName(displayName); setSig(signature); }}>Cancel</button>
          <button
            type="button"
            className="btn btn-primary"
            onClick={() => {
              setDisplayName(name.trim() || displayName);
              setSignature(sig);
              useUI.getState().showToast('Your preferences have been saved.');
            }}
          >
            Save changes
          </button>
        </div>
      )}
      <Row title="Undo send" hint="Cancel a message for a few seconds after you press Send.">
        <select className="set-select" value={undo} onChange={(e) => setUndo(Number(e.target.value))}>
          {[0, 5, 10, 20, 30].map((s) => <option key={s} value={s}>{s === 0 ? 'Off' : `${s} seconds`}</option>)}
        </select>
      </Row>
      <Row title="Maximum page size" hint="Conversations shown per page.">
        <select className="set-select" value={pageSize} onChange={(e) => { setPageSize(Number(e.target.value)); useUI.getState().setPage(0); }}>
          {[25, 50, 100].map((n) => <option key={n} value={n}>{n}</option>)}
        </select>
      </Row>
      <Row title="Density">
        <Radios name="density" value={density} onChange={setDensity} options={[{ value: 'default', label: 'Default' }, { value: 'comfortable', label: 'Comfortable' }, { value: 'compact', label: 'Compact' }]} />
      </Row>
      <Row title="Auto-advance" hint="After archiving, deleting or muting a conversation, go to:">
        <Radios name="advance" value={advance} onChange={setAdvance} options={[{ value: 'list', label: 'Back to the list' }, { value: 'newer', label: 'Newer conversation' }, { value: 'older', label: 'Older conversation' }]} />
      </Row>
      <Row title="Smart reply" hint="Suggest short replies when available.">
        <Switch checked={smartReply} onChange={setSmartReply} label="Smart reply" />
      </Row>
      <Row title="Keyboard shortcuts" hint="Press ? anywhere to see the list.">
        <Switch checked={shortcuts} onChange={setShortcuts} label="Keyboard shortcuts" />
      </Row>
      <Row title="Hover actions" hint="Show archive, delete, read and snooze buttons when hovering a row.">
        <Switch checked={hover} onChange={setHover} label="Hover actions" />
      </Row>
      <Row title="Importance markers" hint="Show the importance arrow next to conversations.">
        <Switch checked={importance} onChange={setImportance} label="Importance markers" />
      </Row>
    </div>
  );
}

function Labels() {
  const labels = useMail((s) => s.labels);
  const threads = useMail((s) => s.threads);
  const update = useMail((s) => s.updateLabel);
  const counts: Record<string, number> = {};
  for (const t of Object.values(threads)) if (!t.trashed) for (const l of t.labels) counts[l] = (counts[l] ?? 0) + 1;
  return (
    <div className="set-group">
      <div className="set-labels-head">
        <h2>Labels</h2>
        <button type="button" className="btn btn-tonal" onClick={() => useUI.getState().set({ labelDialog: { mode: 'create' } })}>Create new label</button>
      </div>
      <table className="label-table">
        <thead>
          <tr><th>Name</th><th>Conversations</th><th>Show in label list</th><th>Actions</th></tr>
        </thead>
        <tbody>
          {labels.map((l) => (
            <tr key={l.id}>
              <td>
                <span className="label-swatch" style={{ background: l.color }} />
                <button type="button" className="link-btn" onClick={() => navigate({ view: 'label', labelId: l.id })}>{l.name}</button>
              </td>
              <td>{counts[l.id] ?? 0}</td>
              <td>
                <div className="seg">
                  <button type="button" className={!l.hidden ? 'is-on' : ''} onClick={() => update(l.id, { hidden: false })}>show</button>
                  <button type="button" className={l.hidden ? 'is-on' : ''} onClick={() => update(l.id, { hidden: true })}>hide</button>
                </div>
              </td>
              <td className="label-actions">
                <button type="button" className="link-btn" onClick={() => useUI.getState().set({ labelDialog: { mode: 'edit', labelId: l.id } })}>edit</button>
                <button
                  type="button"
                  className="link-btn is-danger"
                  onClick={() => {
                    if (window.confirm(`Remove the label “${l.name}”? Conversations won’t be deleted.`)) {
                      useMail.getState().deleteLabel(l.id);
                      useUI.getState().showToast(`Label “${l.name}” removed.`);
                    }
                  }}
                >
                  remove
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <p className="set-note">Tip: drag conversations from the list onto a label in the sidebar to move them there.</p>
      <div className="set-palette" aria-hidden>
        {LABEL_PALETTE.map((p) => <span key={p.color} style={{ background: p.color }} />)}
      </div>
    </div>
  );
}

function Inbox() {
  const [categories, setCategories] = useSetting('categories');
  const [sort, setSort] = useSetting('inboxSort');
  const [pane, setPane] = useSetting('readingPane');
  return (
