  bold?: boolean;
  onClick: () => void;
  onDrop?: (ids: string[]) => void;
  trailing?: ReactNode;
  style?: CSSProperties;
  dotColor?: string;
}) {
  const [over, setOver] = useState(false);
  return (
    <div
      className={`nav-item ${active ? 'is-active' : ''} ${over ? 'is-drop' : ''} ${bold && count ? 'has-unread' : ''}`}
      style={style}
      onDragOver={(e) => {
        if (!onDrop || !useUI.getState().dragIds) return;
