    <svg className="logo-mark" width={size} height={size * 0.75} viewBox="0 0 48 36" aria-hidden>
      <path d="M4 34h8V15L0 6v24c0 2.2 1.8 4 4 4z" fill="#4285f4" />
      <path d="M36 34h8c2.2 0 4-1.8 4-4V6l-12 9z" fill="#34a853" />
