import { useEffect, useRef, useState, useSyncExternalStore } from 'react';

export function useMediaQuery(query: string): boolean {
  return useSyncExternalStore(
    (cb) => {
      const mql = window.matchMedia(query);
      mql.addEventListener('change', cb);
      return () => mql.removeEventListener('change', cb);
    },
    () => window.matchMedia(query).matches,
    () => false,
  );
}

export const MOBILE_QUERY = '(max-width: 720px)';
export const TABLET_QUERY = '(max-width: 1100px)';

export function useIsMobile() {
  return useMediaQuery(MOBILE_QUERY);
}

/** Re-renders periodically so relative times and snooze states stay fresh. */
export function useNow(intervalMs = 30_000): number {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const id = window.setInterval(() => setNow(Date.now()), intervalMs);
    return () => window.clearInterval(id);
  }, [intervalMs]);
  return now;
}

export function useOutsideClick<T extends HTMLElement>(onOutside: () => void, active = true) {
  const ref = useRef<T>(null);
  const cb = useRef(onOutside);
  cb.current = onOutside;
  useEffect(() => {
    if (!active) return;
    const handler = (e: PointerEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) cb.current();
    };
    document.addEventListener('pointerdown', handler, true);
    return () => document.removeEventListener('pointerdown', handler, true);
  }, [active]);
  return ref;
}

export function useDebouncedCallback<A extends unknown[]>(fn: (...args: A) => void, ms: number) {
  const timer = useRef<number | undefined>(undefined);
  const latest = useRef(fn);
  latest.current = fn;
  useEffect(() => () => window.clearTimeout(timer.current), []);
  return (...args: A) => {
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => latest.current(...args), ms);
  };
}

export function useSystemDark() {
  return useMediaQuery('(prefers-color-scheme: dark)');
}

import { useEffect, useRef, useState, type CSSProperties } from 'react';
import { MdCheck, MdClose, MdOutlineMail } from 'react-icons/md';
import { LABEL_PALETTE, ME } from '../data/seed';
import { useIsMobile } from '../hooks';
import { moveTo, openThread, setLabel } from '../lib/actions';
import { navigate } from '../lib/router';
import { useMail, type Density, type ThemeMode, type ThemeTint } from '../store/mail';
import { useUI } from '../store/ui';
import { Logo } from './Header';
import { Avatar, Dialog, IconButton, Switch } from './primitives';

/* ---------------- Toast ---------------- */

export function ToastHost() {
  const toast = useUI((s) => s.toast);
  const [paused, setPaused] = useState(false);
  useEffect(() => {
    if (!toast || paused) return;
    const id = window.setTimeout(() => useUI.getState().dismissToast(toast.id), toast.duration ?? 6000);
    return () => window.clearTimeout(id);
  }, [toast, paused]);
  useEffect(() => setPaused(false), [toast?.id]);
  if (!toast) return null;
  return (
    <div className="toast" role="status" aria-live="polite" onMouseEnter={() => setPaused(true)} onMouseLeave={() => setPaused(false)} key={toast.id}>
      <span className="toast-msg">{toast.message}</span>
      {toast.actions?.map((a) => (
        <button
          key={a.label}
          type="button"
          className="toast-action"
          onClick={() => {
            useUI.getState().dismissToast(toast.id);
            a.run();
          }}
        >
          {a.label}
        </button>
      ))}
      <IconButton icon={MdClose} label="Dismiss" size="sm" className="on-dark" onClick={() => useUI.getState().dismissToast(toast.id)} />
    </div>
  );
}

/* ---------------- Incoming mail notices ---------------- */

export function Notices() {
  const notices = useUI((s) => s.notices);
  return (
    <div className="notices" aria-live="polite">
      {notices.map((n) => (
        <NoticeCard key={n.id} id={n.id} />
      ))}
    </div>
  );
}

function NoticeCard({ id }: { id: string }) {
  const n = useUI((s) => s.notices.find((x) => x.id === id));
  const [hover, setHover] = useState(false);
  useEffect(() => {
    if (hover) return;
    const t = window.setTimeout(() => useUI.getState().dismissNotice(id), 7000);
    return () => window.clearTimeout(t);
  }, [id, hover]);
  if (!n) return null;
  return (
    <div
      className="notice"
      role="button"
      tabIndex={0}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      onClick={() => {
        useUI.getState().dismissNotice(id);
        openThread(n.threadId, { view: 'folder', folder: 'inbox' });
      }}
      onKeyDown={(e) => {
        if (e.key === 'Enter') {
          useUI.getState().dismissNotice(id);
          openThread(n.threadId, { view: 'folder', folder: 'inbox' });
        }
      }}
    >
      <Avatar contact={n.from} size={40} />
      <div className="notice-text">
        <div className="notice-app"><MdOutlineMail aria-hidden /> New mail · now</div>
        <div className="notice-title">{n.title}</div>
        <div className="notice-body">{n.body}</div>
      </div>
      <IconButton
        icon={MdClose}
        size="sm"
        label="Dismiss notification"
        onClick={(e) => {
          e.stopPropagation();
          useUI.getState().dismissNotice(id);
        }}
      />
    </div>
  );
}

/* ---------------- Label dialog ---------------- */

export function LabelDialog() {
  const state = useUI((s) => s.labelDialog);
  const labels = useMail((s) => s.labels);
  const [name, setName] = useState('');
  const [color, setColor] = useState(0);
  const editing = state?.mode === 'edit' ? labels.find((l) => l.id === state.labelId) : undefined;
  useEffect(() => {
    if (!state) return;
    if (editing) {
      setName(editing.name);
      setColor(Math.max(0, LABEL_PALETTE.findIndex((p) => p.color === editing.color)));
    } else {
      setName(state.name ?? '');
      setColor(labels.length % LABEL_PALETTE.length);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state]);
  const close = () => useUI.getState().set({ labelDialog: null });
  const clean = name.trim();
  const duplicate = labels.some((l) => l.name.toLowerCase() === clean.toLowerCase() && l.id !== editing?.id);
  const valid = clean.length > 0 && clean.length <= 40 && !duplicate;
  const save = () => {
    if (!valid || !state) return;
    const mail = useMail.getState();
    if (editing) {
      mail.updateLabel(editing.id, { name: clean, ...LABEL_PALETTE[color] });
      useUI.getState().showToast(`Label “${clean}” updated.`);
    } else {
      const label = mail.createLabel(clean, color);
      if (state.applyTo?.length) {
        if (state.move) moveTo(state.applyTo, { labelId: label.id });
        else setLabel(state.applyTo, label.id, true);
      } else useUI.getState().showToast(`Label “${label.name}” created.`, [{ label: 'View', run: () => navigate({ view: 'label', labelId: label.id }) }]);
    }
    close();
  };
  return (
    <Dialog
      open={!!state}
      onClose={close}
      title={editing ? 'Edit label' : 'New label'}
      actions={
        <>
          <button type="button" className="btn btn-text" onClick={close}>Cancel</button>
          <button type="button" className="btn btn-primary" disabled={!valid} onClick={save}>{editing ? 'Save' : 'Create'}</button>
        </>
      }
    >
      <form
        className="form-stack"
        onSubmit={(e) => {
          e.preventDefault();
          save();
        }}
      >
        <label className="field">
          <span>{editing ? 'Label name' : 'Please enter a new label name'}</span>
          <input value={name} onChange={(e) => setName(e.target.value)} maxLength={40} autoFocus />
        </label>
        {duplicate && <p className="field-error">A label with this name already exists.</p>}
        <div className="field">
          <span>Color</span>
          <div className="swatches swatches-lg">
            {LABEL_PALETTE.map((p, i) => (
              <button
                key={p.color}
                type="button"
                className={`swatch ${i === color ? 'is-on' : ''}`}
                style={{ background: p.color }}
                aria-label={`Color ${i + 1}`}
                aria-pressed={i === color}
                onClick={() => setColor(i)}
              >
                {i === color && <MdCheck aria-hidden />}
              </button>
            ))}
          </div>
        </div>
        {state?.applyTo?.length ? (
          <p className="dialog-note">
            {state.move ? 'Moves' : 'Applies to'} {state.applyTo.length === 1 ? 'the selected conversation' : `${state.applyTo.length} selected conversations`}.
          </p>
        ) : null}
        <button type="submit" hidden />
      </form>
    </Dialog>
  );
}

/* ---------------- Keyboard shortcuts ---------------- */

const SHORTCUTS: { title: string; items: [string, string][] }[] = [
  {
    title: 'Navigation',
    items: [
      ['g then i', 'Go to Inbox'], ['g then s', 'Go to Starred'], ['g then t', 'Go to Sent'], ['g then d', 'Go to Drafts'],
      ['g then a', 'Go to All Mail'], ['g then k', 'Open Tasks'], ['j / k', 'Older / newer conversation'], ['o or Enter', 'Open conversation'],
      ['u', 'Back to list'], ['/', 'Search mail'], ['?', 'Show shortcuts'],
    ],
  },
  {
    title: 'Actions',
    items: [
      ['c', 'Compose'], ['r', 'Reply'], ['a', 'Reply all'], ['f', 'Forward'], ['e', 'Archive'], ['#', 'Delete'], ['!', 'Report spam'],
      ['s', 'Star / unstar'], ['+ / -', 'Mark important / not important'], ['Shift + i', 'Mark as read'], ['Shift + u', 'Mark as unread'],
      ['m', 'Mute'], ['z', 'Undo last action'], ['⌘ + Enter', 'Send (in compose)'],
    ],
  },
  {
    title: 'Selection',
    items: [['x', 'Select conversation'], ['* then a', 'Select all'], ['* then n', 'Select none'], ['* then r / u', 'Select read / unread'], ['* then s', 'Select starred'], ['Shift + click', 'Select a range'], ['Esc', 'Clear selection']],
  },
];

export function ShortcutsHelp() {
  const open = useUI((s) => s.shortcutsHelp);
  const enabled = useMail((s) => s.settings.shortcuts);
  const close = () => useUI.getState().set({ shortcutsHelp: false });
  return (
    <Dialog
      open={open}
      onClose={close}
      wide
      title="Keyboard shortcuts"
      actions={
        <>
          <label className="inline-switch">
            <Switch checked={enabled} onChange={(v) => useMail.getState().updateSettings({ shortcuts: v })} label="Keyboard shortcuts" />
            <span>Shortcuts {enabled ? 'on' : 'off'}</span>
          </label>
          <span className="tb-spacer" />
          <button type="button" className="btn btn-primary" onClick={close}>Done</button>
        </>
      }
    >
      <div className="shortcuts">
        {SHORTCUTS.map((s) => (
          <section key={s.title}>
            <h3>{s.title}</h3>
            <dl>
              {s.items.map(([k, v]) => (
                <div key={k} className="shortcut">
                  <dt>{k.split(/( then | \/ | \+ | or )/).map((p, i) => (/^( then | \/ | \+ | or )$/.test(p) ? <span key={i} className="kbd-sep">{p.trim()}</span> : <kbd key={i}>{p}</kbd>))}</dt>
                  <dd>{v}</dd>
                </div>
              ))}
            </dl>
          </section>
        ))}
      </div>
    </Dialog>
  );
}

/* ---------------- Quick settings ---------------- */

export const TINTS: { id: ThemeTint; label: string; light: string; dark: string }[] = [
  { id: 'default', label: 'Default', light: '#f6f8fc', dark: '#1b1b1d' },
  { id: 'sky', label: 'Sky', light: '#e8f1fd', dark: '#16202e' },
  { id: 'sage', label: 'Sage', light: '#edf4ec', dark: '#18221b' },
  { id: 'rose', label: 'Rose', light: '#fbeef0', dark: '#281a1e' },
  { id: 'sand', label: 'Sand', light: '#f7f1e6', dark: '#241f17' },
  { id: 'slate', label: 'Slate', light: '#eceff3', dark: '#1a1d22' },
];

type InboxType = 'default' | 'plain' | 'unreadFirst' | 'starredFirst';

export function QuickSettings() {
  const open = useUI((s) => s.quickSettings);
  const settings = useMail((s) => s.settings);
  const update = useMail((s) => s.updateSettings);
  const mobile = useIsMobile();
  const ref = useRef<HTMLDivElement>(null);
  const close = () => useUI.getState().set({ quickSettings: false });
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') close();
    };
    const onDown = (e: PointerEvent) => {
      const t = e.target as HTMLElement;
      if (ref.current?.contains(t) || t.closest('[aria-label="Settings"]')) return;
      close();
    };
    document.addEventListener('keydown', onKey);
    document.addEventListener('pointerdown', onDown, true);
    return () => {
      document.removeEventListener('keydown', onKey);
      document.removeEventListener('pointerdown', onDown, true);
    };
  }, [open]);
  if (!open) return null;
  const inboxType: InboxType = settings.categories ? 'default' : settings.inboxSort === 'default' ? 'plain' : settings.inboxSort;
  const radio = <T extends string>(name: string, value: T, current: T, label: string, onPick: (v: T) => void, preview?: string) => (
    <label className={`qs-option ${value === current ? 'is-on' : ''}`}>
      <input type="radio" name={name} checked={value === current} onChange={() => onPick(value)} />
      <span className="qs-radio" aria-hidden />
      <span className="qs-option-label">{label}</span>
      {preview && <span className={`qs-preview qs-preview-${preview}`} aria-hidden><i /><i /><i /></span>}
    </label>
  );
  return (
    <aside className={`quick-settings ${mobile ? 'is-mobile' : ''}`} ref={ref} aria-label="Quick settings">
      <div className="qs-head">
        <h2>Quick settings</h2>
        <IconButton icon={MdClose} label="Close" onClick={close} />
      </div>
      <div className="qs-scroll">
        <button type="button" className="btn btn-tonal qs-all" onClick={() => { close(); navigate({ view: 'settings', tab: 'general' }); }}>
          See all settings
        </button>
        <section className="qs-section">
          <h3>Theme</h3>
          <div className="qs-themes">
            {(['light', 'dark', 'system'] as ThemeMode[]).map((t) => (
              <button key={t} type="button" className={`qs-theme qs-theme-${t} ${settings.theme === t ? 'is-on' : ''}`} onClick={() => update({ theme: t })} aria-pressed={settings.theme === t}>
                <span className="qs-theme-art" aria-hidden />
                <span>{t[0].toUpperCase() + t.slice(1)}</span>
              </button>
            ))}
          </div>
          <div className="qs-tints" role="radiogroup" aria-label="Background tint">
            {TINTS.map((t) => (
              <button
                key={t.id}
                type="button"
                role="radio"
                aria-checked={settings.tint === t.id}
                aria-label={t.label}
                data-tip={t.label}
                className={`qs-tint ${settings.tint === t.id ? 'is-on' : ''}`}
                style={{ '--tint-l': t.light, '--tint-d': t.dark } as CSSProperties}
                onClick={() => update({ tint: t.id })}
              >
                {settings.tint === t.id && <MdCheck aria-hidden />}
              </button>
            ))}
          </div>
        </section>
        <section className="qs-section">
          <h3>Density</h3>
          {radio<Density>('density', 'default', settings.density, 'Default', (v) => update({ density: v }), 'default')}
          {radio<Density>('density', 'comfortable', settings.density, 'Comfortable', (v) => update({ density: v }), 'comfortable')}
          {radio<Density>('density', 'compact', settings.density, 'Compact', (v) => update({ density: v }), 'compact')}
        </section>
        <section className="qs-section">
          <h3>Inbox type</h3>
          {radio<InboxType>('inboxType', 'default', inboxType, 'Default (with tabs)', () => update({ categories: true, inboxSort: 'default' }))}
          {radio<InboxType>('inboxType', 'plain', inboxType, 'Single inbox', () => update({ categories: false, inboxSort: 'default' }))}
          {radio<InboxType>('inboxType', 'unreadFirst', inboxType, 'Unread first', () => update({ categories: false, inboxSort: 'unreadFirst' }))}
          {radio<InboxType>('inboxType', 'starredFirst', inboxType, 'Starred first', () => update({ categories: false, inboxSort: 'starredFirst' }))}
        </section>
        {!mobile && (
          <section className="qs-section">
            <h3>Reading pane</h3>
            {radio('pane', 'none', settings.readingPane, 'No split', (v) => update({ readingPane: v }))}
            {radio('pane', 'right', settings.readingPane, 'Right of inbox', (v) => update({ readingPane: v }))}
          </section>
        )}
        <section className="qs-section">
          <h3>Behavior</h3>
          <label className="qs-switch"><span>Hover actions on rows</span><Switch checked={settings.hoverActions} onChange={(v) => update({ hoverActions: v })} label="Hover actions" /></label>
          <label className="qs-switch"><span>Smart reply suggestions</span><Switch checked={settings.smartReply} onChange={(v) => update({ smartReply: v })} label="Smart reply" /></label>
          <label className="qs-switch"><span>Keyboard shortcuts</span><Switch checked={settings.shortcuts} onChange={(v) => update({ shortcuts: v })} label="Keyboard shortcuts" /></label>
        </section>

import { useEffect, useMemo, useRef, useState } from 'react';
import {
  MdAdd, MdCheckCircle, MdChevronLeft, MdChevronRight, MdClose, MdExpandLess, MdExpandMore, MdOutlineCalendarToday,
  MdOutlineCircle, MdOutlineContacts, MdOutlineDelete, MdOutlineMail, MdOutlineTaskAlt, MdPlace, MdSearch,
} from 'react-icons/md';
import { useIsMobile, useNow } from '../hooks';
import { composeTo, openThread } from '../lib/actions';
import { TIME, displayName } from '../lib/format';
import { navigate } from '../lib/router';
import { useMail, type Settings } from '../store/mail';
import { knownContacts } from '../store/selectors';
import { useUI } from '../store/ui';
import { Avatar, Dialog, IconButton } from './primitives';

type Panel = NonNullable<Settings['sidePanel']>;

const PANELS: { id: Panel; label: string; icon: typeof MdOutlineCalendarToday; color: string }[] = [
  { id: 'calendar', label: 'Calendar', icon: MdOutlineCalendarToday, color: '#1a73e8' },
  { id: 'tasks', label: 'Tasks', icon: MdOutlineTaskAlt, color: '#1e8e3e' },
  { id: 'contacts', label: 'Contacts', icon: MdOutlineContacts, color: '#e37400' },
];

export function AppRail() {
  const panel = useMail((s) => s.settings.sidePanel);
  const update = useMail((s) => s.updateSettings);
  const openTasks = useMail((s) => s.tasks.filter((t) => !t.done).length);
  return (
    <nav className="rail" aria-label="Side panel apps">
      {PANELS.map((p) => (
        <button
          key={p.id}
          type="button"
          className={`rail-btn ${panel === p.id ? 'is-active' : ''}`}
          aria-label={p.label}
          aria-pressed={panel === p.id}
          data-tip={p.label}
          style={{ color: p.color }}
          onClick={() => update({ sidePanel: panel === p.id ? null : p.id })}
        >
          <p.icon aria-hidden />
          {p.id === 'tasks' && openTasks > 0 && <span className="rail-badge">{openTasks}</span>}
        </button>
      ))}
      <span className="rail-sep" />
    </nav>
  );
}

export function SidePanel() {
  const panel = useMail((s) => s.settings.sidePanel);
  const update = useMail((s) => s.updateSettings);
  const mobile = useIsMobile();
  if (!panel) return null;
  const def = PANELS.find((p) => p.id === panel)!;
  return (
    <aside className={`side-panel ${mobile ? 'is-mobile' : ''}`} aria-label={def.label}>
      <div className="sp-head">
        <h2>{def.label}</h2>
        <IconButton icon={MdClose} label={`Close ${def.label}`} onClick={() => update({ sidePanel: null })} />
      </div>
      <div className="sp-body">
        {panel === 'calendar' && <CalendarPanel />}
        {panel === 'tasks' && <TasksPanel />}
        {panel === 'contacts' && <ContactsPanel />}
      </div>
    </aside>
  );
}

/* ---------------- Calendar ---------------- */

const START_HOUR = 7;
const END_HOUR = 21;
const HOUR_PX = 48;

function startOfDay(ts: number) {
  const d = new Date(ts);
  d.setHours(0, 0, 0, 0);
  return d.getTime();
}

function CalendarPanel() {
  const events = useMail((s) => s.events);
  const now = useNow(60_000);
  const [day, setDay] = useState(() => startOfDay(Date.now()));
  const [draft, setDraft] = useState<{ start: number } | null>(null);
  const gridRef = useRef<HTMLDivElement>(null);
  const isToday = day === startOfDay(now);
  const dayEvents = events.filter((e) => e.start >= day && e.start < day + TIME.DAY).sort((a, b) => a.start - b.start);

  useEffect(() => {
    const h = isToday ? new Date(now).getHours() : 9;
    gridRef.current?.scrollTo({ top: Math.max(0, (h - START_HOUR - 1) * HOUR_PX) });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [day]);

  const label = new Date(day).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
  const nowTop = ((now - day) / TIME.HOUR - START_HOUR) * HOUR_PX;

  return (
    <div className="cal">
      <div className="cal-nav">
        <button type="button" className="btn btn-outline btn-sm" onClick={() => setDay(startOfDay(Date.now()))} disabled={isToday}>Today</button>
        <IconButton icon={MdChevronLeft} label="Previous day" onClick={() => setDay(day - TIME.DAY)} />
        <IconButton icon={MdChevronRight} label="Next day" onClick={() => setDay(day + TIME.DAY)} />
        <span className="cal-date">{label}</span>
      </div>
      <div className="cal-grid" ref={gridRef}>
        <div className="cal-hours" style={{ height: (END_HOUR - START_HOUR) * HOUR_PX }}>
          {Array.from({ length: END_HOUR - START_HOUR }, (_, i) => {
            const h = START_HOUR + i;
            return (
              <button
                key={h}
                type="button"
                className="cal-hour"
                style={{ top: i * HOUR_PX, height: HOUR_PX }}
                aria-label={`Create event at ${h}:00`}
                onClick={() => setDraft({ start: day + h * TIME.HOUR })}
              >
                <span className="cal-hour-label">{new Date(day + h * TIME.HOUR).toLocaleTimeString('en-US', { hour: 'numeric' })}</span>
              </button>
            );
          })}
          {dayEvents.map((e) => {
            const top = ((e.start - day) / TIME.HOUR - START_HOUR) * HOUR_PX;
            const height = Math.max(22, ((e.end - e.start) / TIME.HOUR) * HOUR_PX - 2);
            const past = e.end < now;
            return (
              <div key={e.id} className={`cal-event ${past ? 'is-past' : ''}`} style={{ top, height, background: e.color }} title={e.title}>
                <div className="cal-event-title">{e.title}</div>
                {height > 34 && (
                  <div className="cal-event-meta">
                    {fmtTime(e.start)} – {fmtTime(e.end)}
                    {e.location && height > 50 && <><br /><MdPlace aria-hidden /> {e.location}</>}
                  </div>
                )}
                <button
                  type="button"
                  className="cal-event-x"
                  aria-label={`Delete ${e.title}`}
                  onClick={() => {
                    useMail.getState().deleteEvent(e.id);
                    useUI.getState().showToast('Event deleted.', [{ label: 'Undo', run: () => useMail.getState().addEvent(e) }]);
                  }}
                >
                  <MdClose aria-hidden />
                </button>
              </div>
            );
          })}
          {isToday && nowTop >= 0 && nowTop <= (END_HOUR - START_HOUR) * HOUR_PX && <div className="cal-now" style={{ top: nowTop }} aria-hidden />}
        </div>
      </div>
      <button type="button" className="btn btn-tonal cal-add" onClick={() => setDraft({ start: day + (isToday ? Math.min(END_HOUR - 1, new Date(now).getHours() + 1) : 10) * TIME.HOUR })}>
        <MdAdd aria-hidden /> Create event
      </button>
      <EventDialog draft={draft} onClose={() => setDraft(null)} />
    </div>
  );
}

function fmtTime(ts: number) {
  return new Date(ts).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
}

const EVENT_COLORS = ['#039be5', '#33b679', '#e67c73', '#f6bf26', '#8e24aa', '#f4511e'];

function EventDialog({ draft, onClose }: { draft: { start: number } | null; onClose: () => void }) {
  const [title, setTitle] = useState('');
  const [time, setTime] = useState('10:00');
  const [duration, setDuration] = useState(60);
  const [location, setLocation] = useState('');
  const [color, setColor] = useState(EVENT_COLORS[0]);
  useEffect(() => {
    if (!draft) return;
    const d = new Date(draft.start);
    setTitle('');
    setLocation('');
    setDuration(60);
    setTime(`${String(d.getHours()).padStart(2, '0')}:00`);
  }, [draft]);
  if (!draft) return null;
  const save = () => {
    if (!title.trim()) return;
    const [h, m] = time.split(':').map(Number);
    const start = startOfDay(draft.start) + h * TIME.HOUR + m * TIME.MIN;
    useMail.getState().addEvent({ title: title.trim(), start, end: start + duration * TIME.MIN, location: location.trim() || undefined, color });
    useUI.getState().showToast(`“${title.trim()}” added to your calendar.`);
    onClose();
  };
  return (
    <Dialog
      open
      onClose={onClose}
      title="New event"
      actions={
        <>
          <button type="button" className="btn btn-text" onClick={onClose}>Cancel</button>
          <button type="button" className="btn btn-primary" disabled={!title.trim()} onClick={save}>Save</button>

import { useEffect, useMemo, useState } from 'react';
import type { IconType } from 'react-icons';
import {
  MdOutlineCalendarToday, MdOutlineDelete, MdOutlineInbox, MdOutlineInfo, MdOutlineLabel, MdOutlineLocalOffer,
  MdOutlineReport, MdPeopleOutline,
} from 'react-icons/md';
import type { Category } from '../data/types';
import { moveTo, setLabel, snooze, snoozePresets, type Preset } from '../lib/actions';
import { TIME } from '../lib/format';
import { navigate } from '../lib/router';
import { useMail } from '../store/mail';
import { useUI } from '../store/ui';
import { Dialog, Menu, MenuDivider, MenuItem, useAnchor } from './primitives';

interface AnchoredProps {
  anchor: HTMLElement | null;
  open: boolean;
  onClose: () => void;
  ids: string[];
}

function presetTime(p: Preset) {
  const d = new Date(p.at);
  const today = new Date();
  const time = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
  if (d.toDateString() === today.toDateString()) return time;
  return `${d.toLocaleDateString('en-US', { weekday: 'short' })}, ${time}`;
}

export function LabelMenu({ anchor, open, onClose, ids }: AnchoredProps) {
  const labels = useMail((s) => s.labels);
  const threads = useMail((s) => s.threads);
  const [q, setQ] = useState('');
  useEffect(() => {
    if (open) setQ('');
  }, [open]);
  const list = labels.filter((l) => l.name.toLowerCase().includes(q.toLowerCase()));
  const state = (id: string) => {
    const n = ids.filter((t) => threads[t]?.labels.includes(id)).length;
    return n === 0 ? 'none' : n === ids.length ? 'all' : 'some';
  };
  return (
    <Menu anchor={anchor} open={open} onClose={onClose} className="menu-labels" label="Label as">
      <div className="menu-header">Label as:</div>
      <div className="menu-search">
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search labels" aria-label="Search labels" autoFocus />
      </div>
      <div className="menu-scroll">
        {list.map((l) => {
          const s = state(l.id);
          return (
            <MenuItem key={l.id} checked={s === 'all'} onSelect={() => setLabel(ids, l.id, s !== 'all')} trailing={<span className="menu-dot" style={{ background: l.color }} />}>
              {l.name}
              {s === 'some' && <span className="menu-hint"> (some)</span>}
            </MenuItem>
          );
        })}
        {!list.length && <div className="menu-empty">No labels match “{q}”</div>}
      </div>
      <MenuDivider />
      <MenuItem
        onSelect={() => {
          onClose();
          useUI.getState().set({ labelDialog: { mode: 'create', applyTo: ids, name: q } });
        }}
      >
        {q ? `“${q}” (create new)` : 'Create new'}
      </MenuItem>
      <MenuItem onSelect={() => { onClose(); navigate({ view: 'settings', tab: 'labels' }); }}>Manage labels</MenuItem>
    </Menu>
  );
}

const CATEGORY_TARGETS: { id: Category; label: string; icon: typeof MdPeopleOutline }[] = [
  { id: 'primary', label: 'Primary', icon: MdOutlineInbox },
  { id: 'social', label: 'Social', icon: MdPeopleOutline },
  { id: 'updates', label: 'Updates', icon: MdOutlineInfo },
  { id: 'promotions', label: 'Promotions', icon: MdOutlineLocalOffer },
];

export function MoveMenu({ anchor, open, onClose, ids, exclude }: AnchoredProps & { exclude?: string }) {
  const labels = useMail((s) => s.labels);
  const categories = useMail((s) => s.settings.categories);
  const [q, setQ] = useState('');
  useEffect(() => {
    if (open) setQ('');
  }, [open]);
  const match = (s: string) => s.toLowerCase().includes(q.toLowerCase());
  return (
    <Menu anchor={anchor} open={open} onClose={onClose} className="menu-labels" label="Move to">
      <div className="menu-header">Move to:</div>
      <div className="menu-search">
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search" aria-label="Search folders and labels" autoFocus />
      </div>
      <div className="menu-scroll">
        {exclude !== 'inbox' && match('Inbox') && <MenuItem icon={MdOutlineInbox} onSelect={() => { onClose(); moveTo(ids, 'inbox'); }}>Inbox</MenuItem>}
        {categories &&
          CATEGORY_TARGETS.filter((c) => match(c.label)).map((c) => (
            <MenuItem
              key={c.id}
              icon={c.icon}
              onSelect={() => {
                onClose();
                useMail.getState().setCategory(ids, c.id);
                useUI.getState().showToast(`${ids.length === 1 ? 'Conversation' : `${ids.length} conversations`} moved to ${c.label}.`);
                useUI.getState().clearSelection();
              }}
            >
              {c.label}
            </MenuItem>
          ))}
        {labels.filter((l) => match(l.name)).map((l) => (
          <MenuItem key={l.id} icon={MdOutlineLabel} onSelect={() => { onClose(); moveTo(ids, { labelId: l.id }); }}>
            {l.name}
          </MenuItem>
        ))}
        {exclude !== 'spam' && match('Spam') && <MenuItem icon={MdOutlineReport} onSelect={() => { onClose(); moveTo(ids, 'spam'); }}>Spam</MenuItem>}
        {exclude !== 'trash' && match('Trash') && <MenuItem icon={MdOutlineDelete} onSelect={() => { onClose(); moveTo(ids, 'trash'); }}>Trash</MenuItem>}
      </div>
      <MenuDivider />
      <MenuItem onSelect={() => { onClose(); useUI.getState().set({ labelDialog: { mode: 'create', applyTo: ids, move: true } }); }}>Create new</MenuItem>
      <MenuItem onSelect={() => { onClose(); navigate({ view: 'settings', tab: 'labels' }); }}>Manage labels</MenuItem>
    </Menu>
  );
}

export function SnoozeTrigger({ ids, icon: Icon, className = 'icon-btn icon-btn-md' }: { ids: string[]; icon: IconType; className?: string }) {
  const m = useAnchor<HTMLButtonElement>();
  return (
    <>
      <button type="button" className={`${className} ${m.open ? 'is-active' : ''}`} aria-label="Snooze" data-tip="Snooze" onClick={(e) => { e.stopPropagation(); m.toggle(e); }}>
        <Icon aria-hidden />
      </button>
      <SnoozeMenu anchor={m.anchor} open={m.open} onClose={m.close} ids={ids} />
    </>
  );
}

export function SnoozeMenu({ anchor, open, onClose, ids }: AnchoredProps) {
  const [picker, setPicker] = useState(false);
  const presets = useMemo(() => snoozePresets(), [open]); // eslint-disable-line react-hooks/exhaustive-deps
  return (
    <>
      <Menu anchor={anchor} open={open} onClose={onClose} className="menu-snooze" label="Snooze until">
        <div className="menu-header">Snooze until…</div>
        {presets.map((p) => (
          <MenuItem key={p.id} onSelect={() => { onClose(); snooze(ids, p.at); }} hint={presetTime(p)}>
            {p.label}
          </MenuItem>
        ))}
        <MenuDivider />
        <MenuItem icon={MdOutlineCalendarToday} onSelect={() => { onClose(); setPicker(true); }}>Pick date & time</MenuItem>
      </Menu>
      <DateTimeDialog
        open={picker}
        title="Pick date & time"
        confirmLabel="Save"
        onClose={() => setPicker(false)}
        onConfirm={(at) => {
          setPicker(false);
          snooze(ids, at);
        }}
      />
    </>
  );
}

function toLocalInput(ts: number) {
  const d = new Date(ts);
  const pad = (n: number) => String(n).padStart(2, '0');
  return { date: `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`, time: `${pad(d.getHours())}:${pad(d.getMinutes())}` };
}

export function DateTimeDialog({
  open, title, confirmLabel, onClose, onConfirm,
}: { open: boolean; title: string; confirmLabel: string; onClose: () => void; onConfirm: (at: number) => void }) {
  const [date, setDate] = useState('');
  const [time, setTime] = useState('');
  useEffect(() => {
    if (!open) return;
    const init = toLocalInput(Date.now() + TIME.DAY);
    setDate(init.date);
    setTime('08:00');
  }, [open]);
  const at = date && time ? new Date(`${date}T${time}`).getTime() : NaN;
  const valid = Number.isFinite(at) && at > Date.now();
  return (
    <Dialog
      open={open}
      onClose={onClose}
      title={title}
      actions={
        <>
          <button type="button" className="btn btn-text" onClick={onClose}>Cancel</button>
          <button type="button" className="btn btn-primary" disabled={!valid} onClick={() => onConfirm(at)}>{confirmLabel}</button>
        </>
      }
    >
      <div className="dt-fields">
        <label>
          <span>Date</span>
          <input type="date" value={date} min={toLocalInput(Date.now()).date} onChange={(e) => setDate(e.target.value)} />
        </label>
        <label>
          <span>Time</span>
          <input type="time" value={time} onChange={(e) => setTime(e.target.value)} />
        </label>
      </div>
      {!valid && date && time && <p className="field-error">Choose a time in the future.</p>}
      {valid && <p className="dt-preview">{new Date(at).toLocaleString('en-US', { weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit' })}</p>}
    </Dialog>
  );
}

