.tasks-done-toggle { display: flex; align-items: center; gap: 8px; margin: 8px 12px 4px; padding: 8px 12px; border: 0; border-radius: 16px; background: transparent; color: var(--text-2); font: 500 13px var(--font); cursor: pointer; }
