.contacts { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.contacts-search { display: flex; align-items: center; gap: 8px; flex: none; margin: 0 16px 8px; padding: 0 12px; border-radius: 20px; background: var(--search-bg); color: var(--text-3); }
.contacts-search svg { font-size: 20px; }
.contacts-search input { flex: 1; min-width: 0; height: 40px; border: 0; outline: none; background: transparent; font-size: 14px; }
