.contact-row:hover { background: var(--hover); }
.contact-text { flex: 1; min-width: 0; }
.contact-name { overflow: hidden; font-size: 14px; text-overflow: ellipsis; white-space: nowrap; }
.contact-email { overflow: hidden; color: var(--text-3); font-size: 12px; text-overflow: ellipsis; white-space: nowrap; }
.contact-actions { display: flex; opacity: 0; }
.contact-row:hover .contact-actions,
.contact-row:focus-within .contact-actions { opacity: 1; }

/* ============================================================
   Settings page
   ============================================================ */

.settings { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.settings-head { display: flex; align-items: center; gap: 8px; flex: none; padding: 16px 24px 4px; }
.settings-title { margin: 0; font: 400 22px var(--font); }
.settings-tabs { display: flex; flex: none; gap: 0; padding: 0 16px; overflow-x: auto; border-bottom: 1px solid var(--border); scrollbar-width: none; }
.settings-tab { position: relative; flex: none; height: 44px; padding: 0 16px; border: 0; background: transparent; color: var(--text-2); font: 500 14px var(--font); cursor: pointer; }
.settings-tab:hover { background: var(--hover); }
.settings-tab.is-active { color: var(--primary); }
.settings-tab.is-active::after { content: ''; position: absolute; left: 8px; right: 8px; bottom: 0; height: 3px; border-radius: 3px 3px 0 0; background: var(--primary); }
.settings-scroll { flex: 1; min-height: 0; overflow-y: auto; }
.set-group { max-width: 960px; padding: 8px 24px 40px; }
.set-row { display: grid; grid-template-columns: minmax(180px, 280px) 1fr; gap: 24px; padding: 20px 0; border-bottom: 1px solid var(--border); }
.set-title { font-weight: 500; color: var(--text); }
.set-hint { margin-top: 4px; color: var(--text-3); font-size: 13px; line-height: 18px; }
.set-control { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; min-width: 0; }
.set-input { width: min(360px, 100%); }
