.set-select { min-width: 160px; }
.set-save { position: sticky; bottom: 0; z-index: 2; display: flex; justify-content: flex-end; gap: 8px; padding: 12px 0; background: var(--surface); border-bottom: 1px solid var(--border); }
.radios { display: flex; flex-direction: column; }
.set-stack { display: flex; flex-direction: column; gap: 8px; width: min(420px, 100%); }
.set-labels-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 20px 0 12px; }
.set-labels-head h2 { margin: 0; font: 400 18px var(--font); }
.label-table { width: 100%; border-collapse: collapse; font-size: 14px; }
.label-table th { padding: 8px 12px 8px 0; border-bottom: 1px solid var(--border); color: var(--text-3); font-size: 12px; font-weight: 500; text-align: left; }
.label-table td { padding: 10px 12px 10px 0; border-bottom: 1px solid var(--border); vertical-align: middle; }
.label-table td:first-child { display: flex; align-items: center; gap: 10px; }
.label-swatch { width: 12px; height: 12px; flex: none; border-radius: 3px; }
.label-actions { display: flex; gap: 12px; white-space: nowrap; }
.label-table .label-actions { display: table-cell; }
.label-table .label-actions .link-btn + .link-btn { margin-left: 12px; }
.seg { display: inline-flex; overflow: hidden; border: 1px solid var(--border-strong); border-radius: 16px; }
.seg button { height: 28px; padding: 0 12px; border: 0; background: transparent; color: var(--text-2); font-size: 12px; cursor: pointer; }
.seg button + button { border-left: 1px solid var(--border-strong); }
.seg button.is-on { background: var(--primary-soft); color: var(--on-primary-soft); font-weight: 500; }
.set-note { margin: 16px 0 8px; color: var(--text-3); font-size: 13px; }
.set-palette { display: flex; flex-wrap: wrap; gap: 4px; }
.set-palette span { width: 16px; height: 16px; border-radius: 4px; }
.qs-themes-lg { width: min(420px, 100%); margin: 0; }
.tint-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(92px, 1fr)); gap: 12px; width: min(520px, 100%); }
.tint-card { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 0; border: 0; background: transparent; color: var(--text-2); font-size: 12px; cursor: pointer; }
.tint-card-art { display: grid; place-items: center; width: 100%; aspect-ratio: 3 / 2; border: 2px solid var(--border); border-radius: 10px; background: var(--tint-l); color: #1f1f1f; font-size: 22px; }
:root[data-theme='dark'] .tint-card-art { background: var(--tint-d); color: #e3e3e3; }
.tint-card.is-on { color: var(--primary); font-weight: 500; }
.tint-card.is-on .tint-card-art { border-color: var(--primary); }
.set-stats { display: grid; grid-template-columns: repeat(4, minmax(90px, 1fr)); gap: 12px; width: min(520px, 100%); }
.set-stats div { display: flex; flex-direction: column; padding: 12px 14px; border-radius: 12px; background: var(--surface-2); }
.set-stats b { font: 500 20px var(--font); }
.set-stats span { color: var(--text-3); font-size: 12px; }

/* ============================================================
   Responsive
   ============================================================ */

@media (max-width: 1100px) {
  :root { --sidebar-w: 232px; }
  .row-wide .row-sender { flex-basis: 168px; width: 168px; padding-right: 16px; }
  .shortcuts { grid-template-columns: repeat(2, 1fr); }
  .tab-senders { display: none; }
}

@media (max-width: 900px) and (min-width: 721px) {
  .sidebar:not(.is-collapsed) { width: 72px; }
  .sidebar:not(.is-collapsed) .compose-btn { justify-content: center; padding: 0; }
