  .search { max-width: none; flex: none; height: 48px; border-radius: 28px; }
  .search.is-focused { box-shadow: none; }
  .search.has-drop { border-radius: 28px; box-shadow: none; }
  .search-form { padding: 0 4px 0 4px; }
  .search-drop { position: fixed; top: 64px; left: 0; right: 0; bottom: 0; max-height: none; border-radius: 0; border-top: 1px solid var(--border); box-shadow: none; }
  .account-btn { width: 40px; height: 40px; }

  .main { margin: 0; border-radius: 0; }
  .toast { left: 8px; right: 8px; bottom: calc(84px + env(safe-area-inset-bottom)); max-width: none; }
  .notices { top: auto; right: 8px; left: 8px; bottom: calc(84px + env(safe-area-inset-bottom)); }
  .notice { width: 100%; }

  .toolbar-mobile-select { gap: 2px; padding: 0 4px; background: var(--surface); border-bottom: 1px solid var(--border); }
  .toolbar-mobile-select .tb-actions { margin-left: auto; }
  .thread-toolbar.toolbar-mobile { padding: 0 4px; gap: 0; }

  .row { border-bottom: 0; background: var(--surface); }
  .row.is-unread { background: var(--surface); }
  .row:hover { box-shadow: none; }
  .row.is-selected { background: var(--selected); }
  .row-stacked { padding: 10px 16px; }
  .stack-top .row-sender { font-size: 16px; }
  .row-stacked.is-read .row-subject,
  .row-stacked.is-read .sender-name { color: var(--text-2); }
  .row-stacked.is-read .row-snippet { color: var(--text-3); }
  .row-stacked.is-unread .row-snippet { color: var(--text-2); }
  .swipe-fg { background: var(--surface); }
  .list-scroll { padding-bottom: 88px; }

  .thread-head { padding: 16px 16px 8px; }
  .thread-subject { font-size: 20px; line-height: 26px; }
  .thread-subject .row-imp { position: static; margin: -2px 4px 0 -6px; }
  .thread-head-actions { margin-top: -4px; }
  .banners { padding: 0 16px 12px; }
  .msg { padding: 0 12px; }
  .msg.is-collapsed { padding: 12px; }
  .msg.is-expanded { padding: 14px 12px 8px; }
  .msg-meta { margin-top: -6px; }
  .msg-meta .icon-btn { width: 36px; height: 36px; }
  .msg-body.is-rich { margin-left: -52px; margin-right: 0; }
  .reply-zone { padding: 12px 12px 24px; }
  .reply-actions .btn-pill { flex: 1; padding: 0 12px; }
  .inline-compose { padding: 12px 8px 24px; gap: 8px; }
  .inline-avatar { display: none; }
  .att-card { width: calc(50% - 6px); }
  .msg-body.is-rich ~ .msg-atts,
  .msg-atts { margin-left: -52px; }

  .viewer-stage { padding: 8px 8px 56px; }
  .viewer-page { padding: 28px 24px; }
  .viewer-nav { top: auto; bottom: 8px; transform: none; }

  .dialog { border-radius: 20px; }
  .dialog-wide { width: 100%; }
  .shortcuts { grid-template-columns: 1fr; }
  .adv-search { display: none; }

  .settings-head { padding: 8px 8px 0; }
  .set-group { padding: 0 16px 32px; }
  .set-row { grid-template-columns: 1fr; gap: 12px; padding: 16px 0; }
  .set-stats { grid-template-columns: repeat(2, 1fr); }
  .label-table th:nth-child(2),
  .label-table td:nth-child(2) { display: none; }

  .sidebar.is-drawer { position: fixed; top: 0; bottom: 0; left: 0; z-index: 60; width: min(304px, 86vw); background: var(--surface); box-shadow: var(--shadow-4); transform: translateX(-105%); transition: transform 0.22s ease; border-radius: 0 16px 16px 0; }
  .sidebar.is-drawer.is-open { transform: none; }
  .sidebar.is-drawer .nav { padding-right: 12px; }
  .sidebar.is-drawer .nav-item { height: 44px; border-radius: 0 22px 22px 0; }
  .sidebar.is-drawer .nav-more { opacity: 1; }
  .sidebar.is-drawer .nav-item:has(.nav-more) .nav-count { display: none; }
}

@media (hover: none) {
  .row-drag,
  .nav-more { display: none; }
  .nav-item:has(.nav-more) .nav-count { visibility: visible !important; }
  .task-del,
  .contact-actions,
  .cal-event-x { opacity: 1; }
  .att-hover { opacity: 0 !important; }
}

/* ============================================================
   Print
   ============================================================ */

@media print {
  body { overflow: visible; background: #fff; }
  .app { height: auto; background: #fff; }
  .topbar,
  .sidebar,
  .rail,
  .side-panel,
  .toolbar,
  .thread-head-actions,
  .reply-zone,
  .inline-compose,
  .compose-dock,
  .compose-scrim,
  .toast,
  .notices,
  .tooltip,
  .msg-meta .icon-btn,
  .msg-meta .row-star,
  .msg-details-btn,
  .att-hover,
  .fab,
  .quick-settings { display: none !important; }
  .app-body,
  .main,
  .thread,
  .thread-scroll,
  .split,
  .split-pane { display: block; height: auto; overflow: visible; margin: 0; border-radius: 0; }
  .split .list { display: none; }
  .msg.is-collapsed { display: none; }
  .msg { break-inside: avoid; }
  .thread-head,
  .banners { padding-left: 0; }
  .msg-body.is-rich { margin: 0; }
}

