+  --link: #0b57d0;
+  --focus: #0b57d0;
+  --star: #f4b400;
+  --imp: #e8a700;
+  --danger: #d93025;
+  --danger-soft: #fce8e6;
+  --danger-text: #a50e0e;
+  --info-soft: #e8f0fe;
+  --success: #188038;
+  --success-soft: #e6f4ea;
+  --snooze: #b06000;
+  --search-bg: #e9eef6;
+  --chip-sys-bg: #dde3ea;
+  --chip-sys-text: #444746;
+  --tooltip-bg: #3c4043;
+  --tooltip-fg: #ffffff;
+  --toast-bg: #303030;
+  --toast-fg: #f2f2f2;
+  --toast-action: #a8c7fa;
+  --switch-off: #c4c7c5;
+  --switch-thumb-on: #ffffff;
+  --scrim: rgba(32, 33, 36, 0.6);
+  --tab-primary: #0b57d0;
+  --tab-promotions: #188038;
+  --tab-social: #1a73e8;
+  --tab-updates: #e37400;
+  --shadow-1: 0 1px 2px 0 rgba(60, 64, 67, 0.3), 0 1px 3px 1px rgba(60, 64, 67, 0.15);
+  --shadow-2: 0 1px 2px 0 rgba(60, 64, 67, 0.3), 0 2px 6px 2px rgba(60, 64, 67, 0.15);
+  --shadow-3: 0 4px 8px 3px rgba(60, 64, 67, 0.15), 0 1px 3px rgba(60, 64, 67, 0.3);
+  --shadow-4: 0 8px 10px 1px rgba(0, 0, 0, 0.14), 0 3px 14px 2px rgba(0, 0, 0, 0.12), 0 5px 5px -3px rgba(0, 0, 0, 0.2);
+  --row-hover-shadow: inset 1px 0 0 #dadce0, inset -1px 0 0 #dadce0, 0 1px 2px 0 rgba(60, 64, 67, 0.3), 0 1px 3px 1px rgba(60, 64, 67, 0.15);
+
+  --row-h: 40px;
+  --sidebar-w: 256px;
+  --radius: 16px;
+
+  color-scheme: light;
+}
+
+:root[data-tint='sky'] { --bg: #e8f1fd; }
+:root[data-tint='sage'] { --bg: #edf4ec; }
+:root[data-tint='rose'] { --bg: #fbeef0; }
+:root[data-tint='sand'] { --bg: #f7f1e6; }
+:root[data-tint='slate'] { --bg: #eceff3; }
+
+:root[data-theme='dark'] {
+  --bg: #1b1b1d;
+  --surface: #202124;
+  --surface-2: #28292c;
+  --surface-3: #313235;
+  --surface-elev: #2d2e31;
+  --text: #e3e3e3;
+  --text-2: #c4c7c5;
+  --text-3: #9aa0a6;
+  --icon: #c4c7c5;
+  --icon-faint: #6f7377;
+  --border: #3c4043;
+  --border-strong: #5f6368;
+  --row-border: #2c2d30;
+  --row-read: #1c1d20;
+  --row-unread: #26272a;
+  --selected: #1d3557;
+  --hover: rgba(227, 227, 227, 0.08);
+  --hover-strong: rgba(227, 227, 227, 0.14);
+  --pressed: rgba(227, 227, 227, 0.18);
+  --primary: #a8c7fa;
+  --on-primary: #062e6f;
+  --primary-hover: rgba(168, 199, 250, 0.1);
+  --primary-soft: #004a77;
+  --on-primary-soft: #d3e3fd;
+  --compose-bg: #004a77;
+  --compose-text: #c2e7ff;
+  --compose-bar: #2d2e31;
+  --link: #a8c7fa;
+  --focus: #a8c7fa;
+  --star: #fdd663;
+  --imp: #fdd663;
+  --danger: #f28b82;
+  --danger-soft: #3c1f1e;
+  --danger-text: #f6aea9;
+  --info-soft: #1c2b41;
+  --success: #81c995;
+  --success-soft: #1e3526;
+  --snooze: #fdc69c;
+  --search-bg: #2d2e31;
+  --chip-sys-bg: #3c4043;
+  --chip-sys-text: #e3e3e3;
+  --tooltip-bg: #e3e3e3;
+  --tooltip-fg: #1f1f1f;
+  --toast-bg: #e3e3e3;
+  --toast-fg: #1f1f1f;
+  --toast-action: #0b57d0;
+  --switch-off: #5f6368;
+  --switch-thumb-on: #062e6f;
+  --scrim: rgba(0, 0, 0, 0.6);
+  --tab-primary: #a8c7fa;
+  --tab-promotions: #6dd58c;
+  --tab-social: #8ab4f8;
+  --tab-updates: #fcad70;
+  --shadow-1: 0 1px 2px 0 rgba(0, 0, 0, 0.5), 0 1px 3px 1px rgba(0, 0, 0, 0.3);
+  --shadow-2: 0 1px 3px 0 rgba(0, 0, 0, 0.5), 0 4px 8px 3px rgba(0, 0, 0, 0.3);
+  --shadow-3: 0 4px 8px 3px rgba(0, 0, 0, 0.35), 0 1px 3px rgba(0, 0, 0, 0.5);
+  --shadow-4: 0 8px 10px 1px rgba(0, 0, 0, 0.4), 0 3px 14px 2px rgba(0, 0, 0, 0.35), 0 5px 5px -3px rgba(0, 0, 0, 0.5);
+  --row-hover-shadow: inset 1px 0 0 #3c4043, inset -1px 0 0 #3c4043, 0 1px 3px 0 rgba(0, 0, 0, 0.6), 0 2px 6px 2px rgba(0, 0, 0, 0.35);
+  color-scheme: dark;
+}
+
+:root[data-theme='dark'][data-tint='sky'] { --bg: #16202e; }
+:root[data-theme='dark'][data-tint='sage'] { --bg: #18221b; }
+:root[data-theme='dark'][data-tint='rose'] { --bg: #281a1e; }
+:root[data-theme='dark'][data-tint='sand'] { --bg: #241f17; }
+:root[data-theme='dark'][data-tint='slate'] { --bg: #1a1d22; }
+
+:root[data-density='comfortable'] { --row-h: 40px; }
+:root[data-density='compact'] { --row-h: 32px; }
+
+/* ============================================================
+   Base
+   ============================================================ */
+
+*,
+*::before,
+*::after { box-sizing: border-box; }
+
+html,
+body,
+#root { height: 100%; }
+
+body {
+  margin: 0;
+  font-family: var(--font-body);
+  font-size: 14px;
+  line-height: 1.4;
+  color: var(--text);
+  background: var(--bg);
+  -webkit-font-smoothing: antialiased;
+  -moz-osx-font-smoothing: grayscale;
+  -webkit-tap-highlight-color: transparent;
+  overflow: hidden;
+}
+
+button,
+input,
+select,
+textarea { font: inherit; color: inherit; }
+
+button { -webkit-tap-highlight-color: transparent; }
+
+:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
+
+input::placeholder,
+textarea::placeholder { color: var(--text-3); opacity: 1; }
+
+mark { background: #fde293; color: inherit; border-radius: 2px; padding: 0 1px; }
+:root[data-theme='dark'] mark { background: #7a5c00; }
+
+kbd {
+  display: inline-block;
+  min-width: 22px;
+  padding: 1px 6px;
+  border-radius: 4px;
+  border: 1px solid var(--border-strong);
+  border-bottom-width: 2px;
+  background: var(--surface-2);
+  font: 500 12px/18px ui-monospace, SFMono-Regular, Menlo, monospace;
+  text-align: center;
+  color: var(--text);
+}
+
+::-webkit-scrollbar { width: 16px; height: 16px; }
+::-webkit-scrollbar-thumb { background: transparent; border: 4px solid transparent; border-radius: 8px; background-clip: padding-box; }
+:hover::-webkit-scrollbar-thumb { background-color: rgba(128, 134, 139, 0.35); }
+::-webkit-scrollbar-thumb:hover { background-color: rgba(128, 134, 139, 0.6); }
+::-webkit-scrollbar-corner { background: transparent; }
+
+@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
+@keyframes pop-in { from { opacity: 0; transform: scale(0.96); } to { opacity: 1; transform: none; } }
+@keyframes rise-in { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: none; } }
+@keyframes slide-left { from { transform: translateX(24px); opacity: 0; } to { transform: none; opacity: 1; } }
+@keyframes spin { to { transform: rotate(360deg); } }
+
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
+}
+
+/* ============================================================
+   Primitives
+   ============================================================ */
+
+.icon-btn {
+  position: relative;
+  display: inline-grid;
+  place-items: center;
+  flex: none;
+  padding: 0;
+  border: 0;
+  border-radius: 50%;
+  background: transparent;
+  color: var(--icon);
+  cursor: pointer;
+  transition: background-color 0.12s;
+}
+.icon-btn svg { display: block; }
+.icon-btn-sm { width: 32px; height: 32px; font-size: 18px; }
+.icon-btn-md { width: 40px; height: 40px; font-size: 20px; }
+.icon-btn-lg { width: 48px; height: 48px; font-size: 24px; }
+.icon-btn:hover { background: var(--hover); }
+.icon-btn:active { background: var(--pressed); }
+.icon-btn.is-active { background: var(--hover-strong); }
+.icon-btn:disabled { opacity: 0.38; cursor: default; background: transparent; }
+.icon-btn.is-spinning svg { animation: spin 0.7s linear; }
+.icon-btn.on-dark { color: #e8eaed; }
+.icon-btn.on-dark:hover { background: rgba(255, 255, 255, 0.12); }
+
+.checkbox {
+  display: inline-grid;
+  place-items: center;
+  flex: none;
+  width: 40px;
+  height: 40px;
+  padding: 0;
+  border: 0;
+  border-radius: 50%;
+  background: transparent;
+  color: var(--icon-faint);
+  font-size: 20px;
+  cursor: pointer;
+}
+.checkbox:hover { background: var(--hover); color: var(--text); }
+.checkbox.is-checked { color: var(--text); }
+
+.avatar {
+  display: inline-grid;
+  place-items: center;
+  flex: none;
+  border-radius: 50%;
+  color: #fff;
+  font-family: var(--font);
+  font-weight: 500;
+  line-height: 1;
+  letter-spacing: 0.2px;
+  user-select: none;
+  overflow: hidden;
+}
+.avatar-brand { border-radius: 30%; }
+.avatar-check { width: 40px; height: 40px; background: var(--primary) !important; color: var(--on-primary); font-size: 22px; }
+.avatar-draft { width: 40px; height: 40px; background: var(--surface-3); color: var(--text-3); font-size: 20px; }
+
+.label-chip {
+  display: inline-flex;
+  align-items: center;
+  flex: none;
+  max-width: 180px;
+  height: 20px;
+  padding: 0 6px;
+  margin-right: 6px;
+  border-radius: 4px;
+  background: var(--chip);
+  color: var(--chip-text);
+  font: 500 12px/20px var(--font-body);
+  vertical-align: middle;
+}
+.label-chip-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
+.label-chip-system { background: var(--chip-sys-bg); color: var(--chip-sys-text); }
+.label-chip.is-clickable { cursor: pointer; }
+.label-chip.is-clickable:hover { filter: brightness(0.95); }
+.label-chip-x {
+  display: grid;
+  place-items: center;
+  width: 16px;
+  height: 16px;
+  margin: 0 -3px 0 3px;
+  padding: 0;
+  border: 0;
+  border-radius: 50%;
+  background: transparent;
+  color: inherit;
+  font-size: 13px;
+  opacity: 0.7;
+  cursor: pointer;
+}
+.label-chip-x:hover { opacity: 1; background: rgba(0, 0, 0, 0.12); }
+
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 8px;
+  height: 36px;
+  padding: 0 24px;
+  border: 0;
+  border-radius: 18px;
+  background: transparent;
+  color: var(--primary);
+  font: 500 14px/1 var(--font);
+  letter-spacing: 0.1px;
+  white-space: nowrap;
+  cursor: pointer;
+  transition: background-color 0.12s, box-shadow 0.12s;
+}
+.btn svg { font-size: 18px; flex: none; }
+.btn:disabled { opacity: 0.38; cursor: default; box-shadow: none; }
+.btn-primary { background: var(--primary); color: var(--on-primary); }
+.btn-primary:not(:disabled):hover { box-shadow: var(--shadow-1); background: color-mix(in srgb, var(--primary) 92%, var(--on-primary)); }
+.btn-outline { border: 1px solid var(--border-strong); }
+.btn-outline:not(:disabled):hover,
+.btn-text:not(:disabled):hover { background: var(--primary-hover); }
+.btn-text { padding: 0 12px; }
+.btn-tonal { background: var(--primary-soft); color: var(--on-primary-soft); }
+.btn-tonal:not(:disabled):hover { box-shadow: var(--shadow-1); }
+.btn-danger { background: var(--danger); color: #fff; }
+:root[data-theme='dark'] .btn-danger { color: #3c0d0a; }
+.btn-danger:not(:disabled):hover { box-shadow: var(--shadow-1); }
+.btn-pill { height: 36px; padding: 0 20px 0 16px; border: 1px solid var(--border-strong); color: var(--text-2); }
+.btn-pill svg { font-size: 20px; }
+.btn-pill:hover { background: var(--hover); }
+.btn-sm { height: 32px; padding: 0 16px; font-size: 13px; }
+.btn-text.btn-sm { padding: 0 12px; }
+
+.link-btn {
+  padding: 0;
+  border: 0;
+  background: none;
+  color: var(--link);
+  font: inherit;
+  cursor: pointer;
+}
+.link-btn:hover { text-decoration: underline; }
+.link-btn.is-danger { color: var(--danger); }
+
+.switch {
+  position: relative;
+  flex: none;
+  width: 40px;
+  height: 22px;
+  padding: 0;
+  border: 0;
+  border-radius: 11px;
+  background: var(--switch-off);
+  cursor: pointer;
+  transition: background-color 0.15s;
+}
+.switch-thumb {
+  position: absolute;
+  top: 3px;
+  left: 3px;
+  width: 16px;
+  height: 16px;
+  border-radius: 50%;
+  background: #fff;
+  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
+  transition: transform 0.15s, background-color 0.15s;
+}
+.switch.is-on { background: var(--primary); }
+.switch.is-on .switch-thumb { transform: translateX(18px); background: var(--switch-thumb-on); }
+
+.swatches { display: flex; flex-wrap: wrap; gap: 8px; }
+.swatch {
+  display: grid;
+  place-items: center;
+  width: 22px;
+  height: 22px;
+  padding: 0;
+  border: 1px solid rgba(0, 0, 0, 0.12);
+  border-radius: 50%;
+  color: #fff;
+  cursor: pointer;
+}
+.swatch:hover { transform: scale(1.1); }
+.swatch.is-on { box-shadow: 0 0 0 2px var(--surface-elev), 0 0 0 4px var(--text-2); }
+.swatches-lg .swatch { width: 30px; height: 30px; font-size: 18px; }
+.menu .swatches { padding: 4px 16px 8px; max-width: 220px; }
+
+/* Popover + menu */
+
+.popover {
+  position: fixed;
+  z-index: 170;
+  min-width: 180px;
+  overflow: auto;
+  border-radius: 8px;
+  background: var(--surface-elev);
+  color: var(--text);
+  box-shadow: var(--shadow-3);
+  animation: fade-in 0.1s ease-out;
+  overscroll-behavior: contain;
+}
+.menu { min-width: 200px; max-width: 340px; padding: 8px 0; }
+.menu-item {
+  display: flex;
+  align-items: center;
+  gap: 12px;
+  width: 100%;
+  min-height: 32px;
+  padding: 4px 16px;
+  border: 0;
+  background: transparent;
+  color: var(--text);
+  font-size: 14px;
+  text-align: left;
+  white-space: nowrap;
+  cursor: pointer;
+}
+.menu-item:hover,
+.menu-item:focus-visible { background: var(--hover); outline: none; }
+.menu-item:disabled { opacity: 0.4; cursor: default; }
+.menu-item.is-danger { color: var(--danger); }
+.menu-icon { flex: none; font-size: 20px; color: var(--text-2); }
+.menu-item.is-danger .menu-icon { color: inherit; }
+.menu-text { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
+.menu-hint { margin-left: 16px; color: var(--text-3); font-size: 12px; }
+.menu-text .menu-hint { margin-left: 4px; }
+.menu-check { display: inline-flex; font-size: 18px; color: var(--text-3); }
+.menu-check.is-on { color: var(--primary); }
+.menu-divider { height: 1px; margin: 8px 0; background: var(--border); }
+.menu-header { padding: 6px 16px 6px; color: var(--text-3); font: 500 12px var(--font); letter-spacing: 0.2px; }
+.menu-labels { width: 280px; }
+.menu-search { padding: 0 12px 6px; }
+.menu-search input {
+  width: 100%;
+  height: 32px;
+  padding: 0 10px;
+  border: 1px solid var(--border-strong);
+  border-radius: 6px;
+  background: transparent;
+  outline: none;
+  font-size: 13px;
+}
+.menu-search input:focus { border-color: var(--primary); box-shadow: 0 0 0 1px var(--primary); }
+.menu-scroll { max-height: 260px; overflow-y: auto; }
+.menu-dot { width: 10px; height: 10px; flex: none; border-radius: 50%; }
+.menu-empty { padding: 8px 16px; color: var(--text-3); font-size: 13px; }
+.menu-snooze,
+.menu-schedule { min-width: 280px; }
+
+/* Dialog */
+
+.scrim {
+  position: fixed;
+  inset: 0;
+  z-index: 160;
+  display: grid;
+  place-items: center;
+  padding: 24px;
+  background: var(--scrim);
+  animation: fade-in 0.12s ease-out;
+}
+.dialog {
+  display: flex;
+  flex-direction: column;
+  width: min(440px, 100%);
+  max-height: calc(100dvh - 48px);
+  overflow: hidden;
+  border-radius: 16px;
+  background: var(--surface-elev);
+  color: var(--text);
+  box-shadow: 0 24px 38px 3px rgba(0, 0, 0, 0.14), 0 9px 46px 8px rgba(0, 0, 0, 0.12), 0 11px 15px -7px rgba(0, 0, 0, 0.2);
+  animation: pop-in 0.14s ease-out;
+}
+.dialog-wide { width: min(880px, 100%); }
+.dialog-title { margin: 0; padding: 24px 24px 12px; font: 400 22px/28px var(--font); }
+.dialog-body { flex: 1; min-height: 0; overflow: auto; padding: 0 24px 8px; color: var(--text-2); font-size: 14px; line-height: 20px; }
+.dialog-body p { margin: 0 0 12px; }
+.dialog-actions { display: flex; align-items: center; justify-content: flex-end; gap: 8px; padding: 16px 24px 20px; }
+.dialog-note { margin: 0; color: var(--text-3); font-size: 13px; }
+
+.form-stack { display: flex; flex-direction: column; gap: 16px; padding-top: 4px; }
+.field { display: flex; flex-direction: column; gap: 6px; color: var(--text-2); font-size: 12px; font-weight: 500; }
+.field input,
+.field select,
+.dt-fields input,
+.set-input,
+.set-select,
+.set-textarea {
+  height: 40px;
+  padding: 0 12px;
+  border: 1px solid var(--border-strong);
+  border-radius: 6px;
+  background: transparent;
+  color: var(--text);
+  font-size: 14px;
+  font-weight: 400;
+  outline: none;
+}
+.field input:focus,
+.field select:focus,
+.dt-fields input:focus,
+.set-input:focus,
+.set-select:focus,
+.set-textarea:focus { border-color: var(--primary); box-shadow: 0 0 0 1px var(--primary); }
+.field select option,
+.set-select option { background: var(--surface-elev); }
+.field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
+.field-error { margin: 8px 0 0; color: var(--danger); font-size: 13px; }
+.dt-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
+.dt-fields label { display: flex; flex-direction: column; gap: 6px; font-size: 12px; font-weight: 500; }
+.dt-preview { margin: 12px 0 0; color: var(--text); font-size: 14px; }
+
+.tooltip {
+  position: fixed;
+  z-index: 300;
+  max-width: 280px;
+  padding: 4px 8px;
+  border-radius: 4px;
+  background: var(--tooltip-bg);
+  color: var(--tooltip-fg);
+  font: 500 12px/16px var(--font-body);
+  white-space: pre-line;
+  pointer-events: none;
+  animation: fade-in 0.1s ease-out;
+}
+
+/* ============================================================
+   Shell
+   ============================================================ */
+
+.app { display: flex; flex-direction: column; height: 100dvh; background: var(--bg); }
+.app-body { display: flex; flex: 1; min-height: 0; }
+
+.topbar { display: flex; align-items: center; flex: none; gap: 8px; height: 64px; padding: 8px 8px 8px 8px; }
+.topbar-left { display: flex; align-items: center; flex: none; gap: 4px; min-width: calc(var(--sidebar-w) - 16px); padding-right: 12px; }
+.topbar-right { display: flex; align-items: center; gap: 4px; margin-left: auto; padding-right: 4px; }
+
+.brand { display: flex; align-items: center; gap: 8px; padding-left: 4px; color: var(--text-2); text-decoration: none; white-space: nowrap; }
+.brand-name { margin: 0; font: 400 22px/28px var(--font); letter-spacing: -0.2px; color: var(--text-2); }
+.logo-mark { display: block; flex: none; }
+
+.account-btn { display: grid; place-items: center; width: 48px; height: 48px; margin-left: 4px; padding: 0; border: 0; border-radius: 50%; background: transparent; cursor: pointer; }
+.account-btn:hover { background: var(--hover); }
+.account-pop { width: 380px; border-radius: 28px; background: var(--surface-3); }
+.account-card { position: relative; display: flex; flex-direction: column; align-items: center; gap: 12px; padding: 16px 16px 12px; text-align: center; }
+.account-email { font-size: 14px; font-weight: 500; color: var(--text); padding: 4px 40px; }
+.account-close { position: absolute; top: 8px; right: 8px; }
+.account-avatar { margin-top: 4px; }
+.account-hi { font: 400 22px var(--font); }
+.account-card > .btn-outline { color: var(--primary); }
