function parseRelative(v: string, now: number): number | null {
  const m = v.match(/^(\d+)([dmy])$/i);
  if (!m) return null;
  const n = Number(m[1]);
  const unit = m[2].toLowerCase();
  const span = unit === 'd' ? TIME.DAY : unit === 'm' ? 30 * TIME.DAY : 365 * TIME.DAY;
