  .brand-mobile { display: flex; align-items: center; gap: 8px; height: 32px; padding-left: 4px; }
  .brand-mobile .brand-name { font-size: 18px; line-height: 24px; }
  .topbar-mobile:has(.search.is-focused) .brand-mobile { display: none; }
  .search { max-width: none; flex: none; height: 48px; border-radius: 28px; }
  .search.is-focused { box-shadow: none; }
  .search.has-drop { border-radius: 28px; box-shadow: none; }
  .search-form { padding: 0 4px 0 4px; }
  .search-drop { position: fixed; top: 64px; left: 0; right: 0; bottom: 0; max-height: none; border-radius: 0; border-top: 1px solid var(--border); box-shadow: none; }
  .account-btn { width: 40px; height: 40px; }

