  .toolbar-mobile-select { gap: 2px; padding: 0 4px; background: var(--surface); border-bottom: 1px solid var(--border); }
  .toolbar-mobile-select .tb-actions { margin-left: auto; }
  .thread-toolbar.toolbar-mobile { padding: 0 4px; gap: 0; }

  .row { border-bottom: 0; background: var(--surface); }
  .row.is-unread { background: var(--surface); }
  .row:hover { box-shadow: none; }
  .row.is-selected { background: var(--selected); }
  .row-stacked { padding: 10px 16px; }
  .stack-top .row-sender { font-size: 16px; }
  .row-stacked.is-read .row-subject,
  .row-stacked.is-read .sender-name { color: var(--text-2); }
  .row-stacked.is-read .row-snippet { color: var(--text-3); }
  .row-stacked.is-unread .row-snippet { color: var(--text-2); }
  .swipe-fg { background: var(--surface); }
  .list-scroll { padding-bottom: 88px; }

  .thread-head { padding: 16px 16px 8px; }
  .thread-subject { font-size: 20px; line-height: 26px; }
  .thread-subject .row-imp { position: static; margin: -2px 4px 0 -6px; }
  .thread-head-actions { margin-top: -4px; }
  .banners { padding: 0 16px 12px; }
  .msg { padding: 0 12px; }
  .msg-more { padding: 0 12px; }
  .msg.is-collapsed { padding: 12px; }
