  .msg-body.is-rich { margin-left: -52px; margin-right: 0; }
  .reply-zone { padding: 12px 12px 24px; }
  .reply-actions .btn-pill { flex: 1; padding: 0 12px; }
  .inline-compose { padding: 12px 8px 24px; gap: 8px; }
  .inline-avatar { display: none; }
  .att-card { width: calc(50% - 6px); }
  .msg-body.is-rich ~ .msg-atts,
