  .dialog { border-radius: 20px; }
  .dialog-wide { width: 100%; }
  .shortcuts { grid-template-columns: 1fr; }
  .adv-search { display: none; }

  .settings-head { padding: 8px 8px 0; }
  .set-group { padding: 0 16px 32px; }
  .set-row { grid-template-columns: 1fr; gap: 12px; padding: 16px 0; }
  .set-stats { grid-template-columns: repeat(2, 1fr); }
  .label-table th:nth-child(2),
  .label-table td:nth-child(2) { display: none; }

  .sidebar.is-drawer { position: fixed; top: 0; bottom: 0; left: 0; z-index: 60; width: min(304px, 86vw); background: var(--surface); box-shadow: var(--shadow-4); transform: translateX(-105%); transition: transform 0.22s ease; border-radius: 0 16px 16px 0; }
  .sidebar.is-drawer.is-open { transform: none; }
