  .sidebar.is-drawer .nav-more { opacity: 1; }
  .sidebar.is-drawer .nav-item:has(.nav-more) .nav-count { display: none; }
}

@media (hover: none) {
  .row-drag,
  .nav-more { display: none; }
  .nav-item:has(.nav-more) .nav-count { visibility: visible !important; }
  .task-del,
  .contact-actions,
  .cal-event-x { opacity: 1; }
  .att-hover { opacity: 0 !important; }
}

/* ============================================================
   Print
   ============================================================ */

@media print {
  body { overflow: visible; background: #fff; }
  .app { height: auto; background: #fff; }
  .topbar,
  .sidebar,
  .rail,
  .side-panel,
  .toolbar,
  .thread-head-actions,
  .reply-zone,
  .inline-compose,
  .compose-dock,
  .compose-scrim,
  .toast,
  .notices,
  .tooltip,
  .msg-meta .icon-btn,
  .msg-meta .row-star,
  .msg-details-btn,
  .att-hover,
  .fab,
  .quick-settings { display: none !important; }
  .app-body,
  .main,
  .thread,
  .thread-scroll,
  .split,
  .split-pane { display: block; height: auto; overflow: visible; margin: 0; border-radius: 0; }
