const page = await browser.getPage("main");
const out = {};
const errors = [];
page.on("pageerror", (e) => errors.push(e.message));
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
await page.goto("http://localhost:9231/#inbox");
await page.waitForSelector("[data-thread]");

// Thread with the collapsed divider: screenshot, expand, attachments visible
await page.goto("http://localhost:9231/#inbox/t-roadmap-q4");
await page.waitForSelector(".msg-more");
await saveScreenshot(await page.screenshot({ clip: { x: 180, y: 110, width: 900, height: 200 } }), "divider.png");
await page.click(".msg-more");
out.expandedAll = await page.$$eval(".msg", (e) => e.length);
const firstCollapsed = page.locator(".msg.is-collapsed").first();
await firstCollapsed.click();
await page.waitForTimeout(200);
out.attachmentCards = await page.evaluate(() => [...document.querySelectorAll(".msg.is-expanded [class*=att]")].map((e) => e.className).filter((c, i, a) => a.indexOf(c) === i));

// Label via toolbar: select a row, open Labels menu, toggle Finance
await page.goto("http://localhost:9231/#inbox");
await page.waitForSelector("[data-thread]");
const row = page.locator("[data-thread]").nth(6);
const rowId = await row.getAttribute("data-thread");
await row.locator("[role=checkbox]").click();
await page.locator(".toolbar").getByRole("button", { name: "Labels", exact: true }).click();
await page.locator(".menu-labels").getByText("Finance", { exact: true }).click();
await page.keyboard.press("Escape");
await page.waitForTimeout(200);
out.label = await page.evaluate((id) => [...document.querySelectorAll(`[data-thread="${id}"] .label-chip`)].map((c) => c.textContent), rowId);
await page.goto("http://localhost:9231/#label/finance");
await page.waitForSelector("[data-thread]");
out.labelView = await page.evaluate((id) => ({ has: !!document.querySelector(`[data-thread="${id}"]`), rows: document.querySelectorAll("[data-thread]").length }), rowId);

// Search: type + suggestions + Enter
await page.goto("http://localhost:9231/#inbox");
await page.waitForSelector("[data-thread]");
await page.click("input[aria-label='Search mail']");
await page.fill("input[aria-label='Search mail']", "roadmap");
await page.waitForTimeout(250);
out.suggestions = await page.$$eval(".search-drop [role=option], .search-drop li, .search-drop button", (els) => els.slice(0, 6).map((e) => (e.textContent || "").trim().slice(0, 60)));
await page.press("input[aria-label='Search mail']", "Enter");
await page.waitForTimeout(300);
out.search = await page.evaluate(() => ({ hash: decodeURIComponent(location.hash), rows: document.querySelectorAll("[data-thread]").length, marks: document.querySelectorAll("[data-thread] mark").length }));
await page.fill("input[aria-label='Search mail']", "has:attachment from:priya");
await page.press("input[aria-label='Search mail']", "Enter");
await page.waitForTimeout(300);
out.search2 = await page.evaluate(() => ({ hash: decodeURIComponent(location.hash), rows: document.querySelectorAll("[data-thread]").length }));
await page.fill("input[aria-label='Search mail']", "zzqxnothing");
await page.press("input[aria-label='Search mail']", "Enter");
await page.waitForTimeout(300);
out.searchEmpty = await page.evaluate(() => ({ rows: document.querySelectorAll("[data-thread]").length, empty: (document.querySelector(".empty")?.textContent || "").slice(0, 80) }));
out.errors = errors;
console.log(JSON.stringify(out, null, 1));
EOF

