  const lines = signature.split('\n').map((l) => l.trim()).filter(Boolean);
  if (!lines.length) return text;
  const re = new RegExp(`(^|\\n)[^\\S\\n]*--[^\\S\\n]*\\n\\s*${lines.map(escapeRe).join('\\s*\\n\\s*')}[^\\S\\n]*(?=\\n|$)`);
