function ComposeMore({ plain, onPlain, onClear }: { plain: boolean; onPlain: () => void; onClear: () => void }) {
  const m = useAnchor<HTMLButtonElement>();
  return (
    <>
      <IconButton icon={MdMoreVert} label="More options" onClick={m.toggle} active={m.open} />
