function LinkDialog({ open, initialText, onClose, onInsert }: { open: boolean; initialText: string; onClose: () => void; onInsert: (text: string, url: string) => void }) {
  const [text, setText] = useState('');
  const [url, setUrl] = useState('');
  useEffect(() => {
    if (open) {
      setText(initialText);
      setUrl('');
    }
