/* ---------------- Emoji + link ---------------- */

const EMOJI = ['😀', '😄', '😊', '😉', '😍', '🤩', '🙂', '🤔', '😅', '😂', '🙌', '👏', '👍', '👎', '🙏', '💪', '👀', '🎉', '🔥', '✨', '❤️', '💙', '💚', '☕', '🍂', '🌧️', '☀️', '🏃', '✈️', '🏔️', '📎', '📅', '✅', '❌', '⚠️', '💡', '📌', '🚀', '🦃', '🥧'];

function EmojiButton({ onPick, onOpen }: { onPick: (e: string) => void; onOpen: () => void }) {
  const m = useAnchor<HTMLButtonElement>();
  return (
    <>
      <button
        type="button"
        className={`icon-btn icon-btn-md ${m.open ? 'is-active' : ''}`}
