function FmtButton({ icon: Icon, label, active, onClick }: { icon: IconType; label: string; active?: boolean; onClick: () => void }) {
  return (
    <button
      type="button"
      className={`fmt-btn ${active ? 'is-active' : ''}`}
      aria-label={label}
      aria-pressed={active ?? undefined}
      data-tip={label}
      onMouseDown={(e) => e.preventDefault()}
      onClick={onClick}
    >
      <Icon aria-hidden />
    </button>
