    case 'starred':
      return live && t.starred;
    case 'snoozed':
      return live && isSnoozed(t, now);
    case 'important':
      return live && t.important;
    case 'sent':
      return live && isSentByMe(t);
    case 'all':
      return live;
    case 'spam':
      return t.spam && !t.trashed;
