dev-browser --browser opus-mail --headless --timeout 120 <<'EOF'
const page = await browser.getPage("main");
const W = ".compose-dock .compose";
const out = {};
const errors = [];
page.on("pageerror", (e) => errors.push(e.message));
page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
await page.goto("http://localhost:9231/#inbox");
await page.evaluate(() => { localStorage.clear(); location.reload(); });
await page.waitForTimeout(800);
await page.waitForSelector("[data-thread]");

await page.locator(".sidebar").getByRole("button", { name: "Compose" }).click();
await page.waitForSelector(W);
await page.fill(`${W} input[aria-label='Subject']`, "Caret check");
const box = await page.locator(`${W} [aria-label='Message body']`).boundingBox();
await page.mouse.click(box.x + box.width / 2, box.y + box.height - 20);
await page.keyboard.type("Typed first.");
await page.waitForTimeout(1200);
out.editorText = await page.$eval(`${W} [aria-label='Message body']`, (e) => e.innerText);
await page.locator(W).getByRole("button", { name: "Save & close" }).click();
await page.goto("http://localhost:9231/#drafts");
await page.waitForSelector("[data-draft]");
out.snippet = (await page.locator("[data-draft]").first().textContent()).slice(0, 80);

// Keyboard shortcuts smoke: j/k cursor, x select, e archive, g then s
await page.goto("http://localhost:9231/#inbox");
await page.waitForSelector("[data-thread]");
await page.locator("body").click({ position: { x: 5, y: 600 } }).catch(() => {});
const firstId = await page.locator("[data-thread]").first().getAttribute("data-thread");
await page.keyboard.press("j");
await page.keyboard.press("k");
await page.keyboard.press("x");
out.selectedByX = await page.locator("[data-thread].is-selected").count();
await page.keyboard.press("e");
await page.waitForTimeout(300);
out.archivedByE = { toast: await page.textContent(".toast-msg").catch(() => null), gone: !(await page.$$eval("[data-thread]", (e) => e.map((x) => x.getAttribute("data-thread")))).includes(firstId) };
await page.keyboard.press("z");
await page.waitForTimeout(300);
out.undoByZ = (await page.$$eval("[data-thread]", (e) => e.map((x) => x.getAttribute("data-thread")))).includes(firstId);
await page.keyboard.press("g");
await page.keyboard.press("s");
await page.waitForTimeout(300);
out.gs = await page.evaluate(() => location.hash);
await page.keyboard.press("?");
await page.waitForTimeout(200);
out.help = await page.locator(".shortcuts, [aria-label='Keyboard shortcuts']").count();
await page.keyboard.press("Escape");
out.errors = errors;
console.log(JSON.stringify(out, null, 1));
EOF

