      onDragLeave={() => setOver(false)}
      onDrop={(e) => {
        setOver(false);
        const ids = readDrag(e);
        if (ids?.length && onDrop) {
          e.preventDefault();
          onDrop(ids);
        }
      }}
    >
      <button type="button" className="nav-link" onClick={onClick} aria-current={active ? 'page' : undefined} data-tip={label}>
