                  onDrop={(ids) => moveTo(ids, { labelId: l.id })}
                  trailing={<LabelItemMenu labelId={l.id} />}
                />
              );
            })}
          </nav>
          {!collapsed && (
            <div className="sidebar-foot">
              <span>Stored locally · works offline</span>
            </div>
          )}
        </div>
      </aside>
    </>
  );
}

