/*
 * Sanity checks for src/data/seedPersonal.ts.
 * Run: node --experimental-strip-types scripts/check-personal.ts
 */
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { CONTACTS } from '../src/data/contacts.ts';
import { PERSONAL, PERSONAL_CONTACTS, SEED_DRAFTS } from '../src/data/seedPersonal.ts';

const here = dirname(fileURLToPath(import.meta.url));
const errors: string[] = [];
const warnings: string[] = [];

const AGO = /^(\d+m|\d+h|\d+d@\d{2}:\d{2})$/;
const LABELS = new Set(['work', 'personal', 'travel', 'finance', 'receipts', 'clients']);
const CATEGORIES = new Set(['primary', 'promotions', 'social', 'updates']);
const LOCATIONS = new Set(['inbox', 'archive', 'spam', 'trash', 'sent']);
const DOC_EXT = /\.(pdf|docx?|xlsx?|pptx?|csv|txt)$/i;
const IMG_EXT = /\.(jpe?g|png|gif|webp|heic)$/i;
const EXACT_DATE = /\b(Jan(uary)?|Feb(ruary)?|Mar(ch)?|Apr(il)?|May|June?|July?|Aug(ust)?|Sep(t(ember)?)?|Oct(ober)?|Nov(ember)?|Dec(ember)?)\.? \d{1,2}(st|nd|rd|th)?\b|\b\d{1,2}\/\d{1,2}(\/\d{2,4})?\b|\bthe \d{1,2}(st|nd|rd|th)\b/;

/** Approximate minutes-ago, assuming "now" is `nowTod` minutes after local midnight. */
function minutesAgo(at: string, nowTod: number): number {
  let m = at.match(/^(\d+)m$/);
  if (m) return Number(m[1]);
  m = at.match(/^(\d+)h$/);
  if (m) return Number(m[1]) * 60;
  m = at.match(/^(\d+)d@(\d{2}):(\d{2})$/);
  if (m) return Number(m[1]) * 1440 + nowTod - (Number(m[2]) * 60 + Number(m[3]));
  return NaN;
}

function checkAgo(at: string, where: string) {
  if (!AGO.test(at)) {
    errors.push(`${where}: invalid at "${at}"`);
    return;
  }
  const m = at.match(/@(\d{2}):(\d{2})$/);
  if (m && (Number(m[1]) > 23 || Number(m[2]) > 59)) errors.push(`${where}: impossible time "${at}"`);
}

/* ---------- Contacts ---------- */
const knownKeys = new Set([...Object.keys(CONTACTS), ...Object.keys(PERSONAL_CONTACTS), 'me']);
for (const key of Object.keys(PERSONAL_CONTACTS)) {
  if (key in CONTACTS) errors.push(`PERSONAL_CONTACTS key "${key}" collides with CONTACTS`);
  if (key === 'me') errors.push('PERSONAL_CONTACTS must not define "me"');
  if (!key.startsWith('p_')) warnings.push(`PERSONAL_CONTACTS key "${key}" is not prefixed with p_`);
  const c = PERSONAL_CONTACTS[key];
  if (c.kind !== 'person' && c.kind !== 'brand') errors.push(`PERSONAL_CONTACTS.${key}: kind must be person or brand`);
}
const usedKeys = new Set<string>();
function checkKey(key: string, where: string) {
  usedKeys.add(key);
  if (!knownKeys.has(key)) errors.push(`${where}: unknown contact key "${key}"`);
}

/* ---------- Thread ids ---------- */
const workSource = readFileSync(join(here, '../src/data/seedThreads.ts'), 'utf8');
const workIds = new Set([...workSource.matchAll(/\bid:\s*'([^']+)'/g)].map((m) => m[1]));
const seenIds = new Set<string>();
for (const t of PERSONAL) {
  if (seenIds.has(t.id)) errors.push(`duplicate thread id "${t.id}"`);
  seenIds.add(t.id);
  if (workIds.has(t.id)) errors.push(`thread id "${t.id}" collides with seedThreads.ts`);
}

/* ---------- Threads ---------- */
const TODS = [0, 8 * 60, 12 * 60, 17 * 60, 1440];
let snoozed = 0;
for (const t of PERSONAL) {
  const loc = t.location ?? 'inbox';
  const where = `thread ${t.id}`;
  if (!t.subject.trim()) errors.push(`${where}: empty subject`);
  if (!CATEGORIES.has(t.category)) errors.push(`${where}: bad category ${t.category}`);
  if (!LOCATIONS.has(loc)) errors.push(`${where}: bad location ${loc}`);
  if (!t.messages.length) errors.push(`${where}: no messages`);
  for (const l of t.labels ?? []) if (!LABELS.has(l)) errors.push(`${where}: label "${l}" not allowed`);
  if ((t.labels ?? []).length > 2) warnings.push(`${where}: more than 2 labels`);
  if (t.unread && loc !== 'inbox') errors.push(`${where}: unread but not in inbox`);
  if (t.snoozeHours) {
    snoozed++;
    if (loc !== 'inbox') errors.push(`${where}: snoozed but not in inbox`);
  }
  if (loc === 'sent' && t.messages.some((m) => m.from !== 'me')) errors.push(`${where}: sent thread has a message not from "me"`);

  t.messages.forEach((m, i) => {
    const mw = `${where} m${i}`;
    checkAgo(m.at, mw);
    checkKey(m.from, `${mw}.from`);
    if (!m.to.length) errors.push(`${mw}: empty "to"`);
    m.to.forEach((k) => checkKey(k, `${mw}.to`));
    (m.cc ?? []).forEach((k) => checkKey(k, `${mw}.cc`));
    if (m.html) errors.push(`${mw}: html bodies are not allowed here`);
    if (!m.body?.trim()) errors.push(`${mw}: empty body`);
    if (m.body && /^>|^On .+ wrote:$/m.test(m.body)) errors.push(`${mw}: body contains quoted history`);
    if (m.body && /lorem ipsum|\bTODO\b|\bTBD\b|\[.+?\]/i.test(m.body)) warnings.push(`${mw}: possible placeholder text`);
    if (m.body && EXACT_DATE.test(m.body)) warnings.push(`${mw}: possible exact date "${m.body.match(EXACT_DATE)?.[0]}"`);
    for (const a of m.attachments ?? []) {
      if (!(a.size > 0)) errors.push(`${mw}: attachment ${a.name} has no size`);
      if (DOC_EXT.test(a.name)) {
        const lines = (a.preview ?? '').split('\n').filter((l) => l.trim()).length;
        if (!a.preview) errors.push(`${mw}: document ${a.name} has no preview`);
        else if (lines < 4 || lines > 14) warnings.push(`${mw}: ${a.name} preview has ${lines} non-empty lines`);
      }
      if (IMG_EXT.test(a.name) && a.preview) warnings.push(`${mw}: image ${a.name} has a preview`);
    }
  });

  for (const tod of TODS) {
    for (let i = 1; i < t.messages.length; i++) {
      const prev = minutesAgo(t.messages[i - 1].at, tod);
      const cur = minutesAgo(t.messages[i].at, tod);
      if (cur > prev) {
        errors.push(`${where}: m${i} (${t.messages[i].at}) is older than m${i - 1} (${t.messages[i - 1].at}) when now=${Math.floor(tod / 60)}:00`);
      }
    }
  }
}
if (snoozed !== 1) errors.push(`expected exactly 1 snoozed thread, found ${snoozed}`);

/* ---------- Drafts ---------- */
if (SEED_DRAFTS.length !== 4) errors.push(`expected 4 drafts, found ${SEED_DRAFTS.length}`);
SEED_DRAFTS.forEach((d, i) => {
  const where = `draft ${i}`;
  checkAgo(d.at, where);
  d.to.forEach((k) => checkKey(k, `${where}.to`));
  (d.cc ?? []).forEach((k) => checkKey(k, `${where}.cc`));
  if (!d.body.trim()) errors.push(`${where}: empty body`);
  if (d.threadId !== undefined && d.threadId !== 't-tidewater-questions') errors.push(`${where}: unexpected threadId ${d.threadId}`);
  if (d.threadId && !workIds.has(d.threadId)) errors.push(`${where}: threadId ${d.threadId} not found in seedThreads.ts`);
});
const replyDrafts = SEED_DRAFTS.filter((d) => d.threadId);
if (replyDrafts.length !== 1) errors.push(`expected exactly 1 reply draft, found ${replyDrafts.length}`);
const scheduled = SEED_DRAFTS.filter((d) => d.scheduleInHours);
if (scheduled.length !== 1 || scheduled[0].scheduleInHours !== 24) errors.push('expected exactly 1 draft scheduled in 24h');

/* ---------- Report ---------- */
const count = <T>(xs: T[], f: (x: T) => boolean) => xs.filter(f).length;
const byLocation: Record<string, number> = {};
for (const t of PERSONAL) byLocation[t.location ?? 'inbox'] = (byLocation[t.location ?? 'inbox'] ?? 0) + 1;
const latestMinutes = (t: (typeof PERSONAL)[number]) => minutesAgo(t.messages[t.messages.length - 1].at, 12 * 60);
const buckets = { '<12h': 0, '12h-7d': 0, '8d-200d': 0, '200d-270d': 0, '>270d': 0 };
for (const t of PERSONAL) {
  const m = latestMinutes(t);
  if (m < 12 * 60) buckets['<12h']++;
  else if (m < 8 * 1440) buckets['12h-7d']++;
  else if (m < 200 * 1440) buckets['8d-200d']++;
  else if (m <= 270 * 1440) buckets['200d-270d']++;
  else buckets['>270d']++;
}
const sent = PERSONAL.filter((t) => t.location === 'sent');

console.log(`threads: ${PERSONAL.length}`);
console.log('by location:', byLocation);
console.log(`unread: ${count(PERSONAL, (t) => !!t.unread)} · starred: ${count(PERSONAL, (t) => !!t.starred)} · important: ${count(PERSONAL, (t) => !!t.important)} · snoozed: ${snoozed}`);
console.log(`with attachments: ${count(PERSONAL, (t) => t.messages.some((m) => (m.attachments ?? []).length > 0))} (attachments total: ${PERSONAL.reduce((n, t) => n + t.messages.reduce((k, m) => k + (m.attachments ?? []).length, 0), 0)})`);
console.log(`single-message: ${count(PERSONAL, (t) => t.messages.length === 1)} · labelled: ${count(PERSONAL, (t) => (t.labels ?? []).length > 0)} · messages: ${PERSONAL.reduce((n, t) => n + t.messages.length, 0)}`);
console.log(`sent: ${sent.length} (last 7d: ${count(sent, (t) => latestMinutes(t) < 7 * 1440)}, with attachments: ${count(sent, (t) => t.messages.some((m) => (m.attachments ?? []).length > 0))})`);
console.log('latest-message age:', buckets);
console.log(`drafts: ${SEED_DRAFTS.length} (reply: ${replyDrafts.length}, scheduled: ${scheduled.length})`);
console.log(`contact keys used: ${usedKeys.size} · new PERSONAL_CONTACTS: ${Object.keys(PERSONAL_CONTACTS).join(', ') || '(none)'}`);

for (const w of warnings) console.warn(`WARN  ${w}`);
if (errors.length) {
  for (const e of errors) console.error(`ERROR ${e}`);
  console.error(`\n${errors.length} error(s)`);
  process.exit(1);
}
console.log('\nOK — all checks passed');

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { CONTACTS } from '../src/data/contacts.ts';
import { AUTOMATED, AUTOMATED_CONTACTS } from '../src/data/seedAutomated.ts';

const here = path.dirname(fileURLToPath(import.meta.url));
const dataDir = path.join(here, '..', 'src', 'data');

const errors: string[] = [];
const warnings: string[] = [];
const err = (m: string) => errors.push(m);
const warn = (m: string) => warnings.push(m);

const ALLOWED_LABELS = new Set(['work', 'personal', 'travel', 'finance', 'receipts', 'clients']);
const AT_RE = /^(\d+m|\d+h|\d+d@\d{2}:\d{2})$/;
/* "Today" is assumed to be 08:24 local when converting d@HH:MM to minutes ago. */
const NOW_MINUTES = 8 * 60 + 24;

function minutesAgo(at: string): number {
  const m = at.match(/^(\d+)m$/);
  if (m) return Number(m[1]);
  const h = at.match(/^(\d+)h$/);
  if (h) return Number(h[1]) * 60;
  const d = at.match(/^(\d+)d@(\d{2}):(\d{2})$/);
  if (d) return Number(d[1]) * 1440 + NOW_MINUTES - (Number(d[2]) * 60 + Number(d[3]));
  return NaN;
}

function scanIds(file: string): string[] {
  const p = path.join(dataDir, file);
  if (!fs.existsSync(p)) return [];
  const text = fs.readFileSync(p, 'utf8');
  return [...text.matchAll(/\bid:\s*['"`]([^'"`]+)['"`]/g)].map((x) => x[1]);
}

/* ---------- Contacts ---------- */
for (const key of Object.keys(AUTOMATED_CONTACTS)) {
  if (key in CONTACTS) err(`AUTOMATED_CONTACTS key collides with CONTACTS: ${key}`);
  if (!key.startsWith('a_')) err(`AUTOMATED_CONTACTS key must start with a_: ${key}`);
  const c = AUTOMATED_CONTACTS[key];
  if (c.kind !== 'brand') err(`AUTOMATED_CONTACTS.${key} must be kind 'brand'`);
  if (!c.color || !/^#[0-9a-f]{6}$/i.test(c.color)) err(`AUTOMATED_CONTACTS.${key} needs a hex color`);
}
if (Object.keys(AUTOMATED_CONTACTS).length > 6) err('More than 6 new contacts');
const knownContact = (k: string) => k === 'me' || k in CONTACTS || k in AUTOMATED_CONTACTS;

/* ---------- Ids ---------- */
const otherIds = new Set([...scanIds('seedThreads.ts'), ...scanIds('seedPersonal.ts')]);
const personalExists = fs.existsSync(path.join(dataDir, 'seedPersonal.ts'));
const seen = new Set<string>();

/* ---------- Threads ---------- */
const byCategory: Record<string, number> = {};
const byLocation: Record<string, number> = {};
const buckets = { last12h: 0, d1to7: 0, older: 0, over270d: 0 };
let unread = 0;
let unreadInbox = 0;
let unreadLast12h = 0;
let starred = 0;
let important = 0;
let snoozed = 0;
let htmlCount = 0;
let attachmentCount = 0;
let maxHtml = 0;

for (const t of AUTOMATED) {
  const where = `[${t.id}]`;
  if (seen.has(t.id)) err(`${where} duplicate id`);
  seen.add(t.id);
  if (otherIds.has(t.id)) err(`${where} id collides with seedThreads/seedPersonal`);
  if (t.id.startsWith('t-p-')) err(`${where} id uses reserved personal prefix t-p-`);
  if (!t.subject.trim()) err(`${where} empty subject`);
  if (!t.messages.length) err(`${where} has no messages`);

  for (const l of t.labels ?? []) if (!ALLOWED_LABELS.has(l)) err(`${where} label not allowed: ${l}`);

  const loc = t.location ?? 'inbox';
  byCategory[t.category] = (byCategory[t.category] ?? 0) + 1;
  byLocation[loc] = (byLocation[loc] ?? 0) + 1;
  if (t.starred) starred++;
  if (t.important) important++;
  if (t.snoozeHours) {
    snoozed++;
    if (loc !== 'inbox') err(`${where} snoozed thread must be in inbox`);
  }

  let prev = Infinity;
  t.messages.forEach((m, i) => {
    const mw = `${where} m${i}`;
    if (!AT_RE.test(m.at)) err(`${mw} bad at: ${m.at}`);
    const mins = minutesAgo(m.at);
    if (mins < 0) err(`${mw} at is in the future relative to 08:24: ${m.at}`);
    if (mins > prev) err(`${mw} not chronological (${m.at})`);
    prev = mins;
    for (const k of [m.from, ...m.to, ...(m.cc ?? [])]) if (!knownContact(k)) err(`${mw} unknown contact: ${k}`);
    if (!m.body && !m.html) err(`${mw} has neither body nor html`);
    if (m.html) {
      htmlCount++;
      maxHtml = Math.max(maxHtml, m.html.length);
      const lower = m.html.toLowerCase();
      for (const bad of ['<script', '<style', '<img']) if (lower.includes(bad)) err(`${mw} html contains ${bad}`);
      if (m.html.length >= 4000) err(`${mw} html is ${m.html.length} chars (>= 4000)`);
      else if (m.html.length > 3500) warn(`${mw} html is ${m.html.length} chars (> 3500)`);
      if (!m.html.includes('max-width:600px')) warn(`${mw} html missing max-width:600px container`);
      const hrefs = [...m.html.matchAll(/href="([^"]*)"/g)].map((x) => x[1]);
      for (const h of hrefs) if (h !== '#' && !h.startsWith('https://')) err(`${mw} suspicious href: ${h}`);
    }
    for (const a of m.attachments ?? []) {
      attachmentCount++;
      const isDoc = /\.(pdf|docx?|xlsx?|pptx?|txt)$/i.test(a.name);
      if (isDoc) {
        const lines = (a.preview ?? '').split('\n').length;
        if (!a.preview) err(`${mw} document attachment ${a.name} needs a preview`);
        else if (lines < 4 || lines > 12) err(`${mw} preview for ${a.name} has ${lines} lines (want 4–12)`);
      }
      if (!(a.size > 0)) err(`${mw} attachment ${a.name} needs a positive size`);
    }
  });

  const last = minutesAgo(t.messages[t.messages.length - 1].at);
  if (last <= 12 * 60) buckets.last12h++;
  else if (last <= 7 * 1440) buckets.d1to7++;
  else buckets.older++;
  if (last > 270 * 1440) buckets.over270d++;

  if (t.unread) {
    unread++;
    if (loc === 'inbox') unreadInbox++;
    if (last <= 12 * 60) unreadLast12h++;
  }
}

/* ---------- Source-level checks ---------- */
const src = fs.readFileSync(path.join(dataDir, 'seedAutomated.ts'), 'utf8');
const interpolations = (src.match(/\$\{/g) ?? []).length;
if (interpolations) warn(`seedAutomated.ts contains ${interpolations} "\${" sequence(s)`);

/* ---------- Targets ---------- */
const n = AUTOMATED.length;
if (n < 44 || n > 50) err(`thread count ${n} outside 44–50`);
if ((byLocation.spam ?? 0) !== 5) err(`spam count ${byLocation.spam ?? 0} !== 5`);
if ((byLocation.trash ?? 0) !== 3) err(`trash count ${byLocation.trash ?? 0} !== 3`);
if ((byLocation.archive ?? 0) !== 6) err(`archive count ${byLocation.archive ?? 0} !== 6`);
if (snoozed !== 1) err(`snoozed count ${snoozed} !== 1`);
if (starred !== 2) err(`starred count ${starred} !== 2`);
if (important !== 3) err(`important count ${important} !== 3`);
if (unread < 12 || unread > 15) err(`unread count ${unread} outside 12–15`);
if (htmlCount < 14 || htmlCount > 16) err(`html count ${htmlCount} outside 14–16`);
if (attachmentCount < 4 || attachmentCount > 6) err(`attachment count ${attachmentCount} outside 4–6`);
const spamUnread = AUTOMATED.filter((t) => t.location === 'spam' && t.unread).length;
if (spamUnread !== 3) err(`unread spam ${spamUnread} !== 3`);

/* ---------- Report ---------- */
console.log(`Threads: ${n}`);
console.log('By category:', byCategory);
console.log('By location:', byLocation);
console.log(`Unread: ${unread} (inbox ${unreadInbox}, last 12h ${unreadLast12h}, spam ${spamUnread})`);
console.log(`Starred: ${starred} · Important: ${important} · Snoozed: ${snoozed}`);
console.log(`HTML bodies: ${htmlCount} (largest ${maxHtml} chars) · Attachments: ${attachmentCount}`);
console.log('Recency of last message:', buckets);
console.log(`New contacts: ${Object.keys(AUTOMATED_CONTACTS).join(', ') || '(none)'}`);
console.log(`Checked ids against seedThreads.ts${personalExists ? ' + seedPersonal.ts' : ''} (${otherIds.size} ids)`);
for (const w of warnings) console.log(`WARN  ${w}`);
if (errors.length) {
  for (const e of errors) console.error(`ERROR ${e}`);
  process.exit(1);
}
console.log('OK');

import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const root = new URL('../src/', import.meta.url).pathname;
const css = readFileSync(join(root, 'styles.css'), 'utf8');
const defined = new Set([...css.matchAll(/\.([a-zA-Z][\w-]*)/g)].map((m) => m[1]));

const files = [];
const walk = (dir) => {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    const p = join(dir, e.name);
    if (e.isDirectory()) walk(p);
    else if (p.endsWith('.tsx')) files.push(p);
  }
};
walk(root);

const used = new Map();
for (const f of files) {
  const src = readFileSync(f, 'utf8');
  for (const m of src.matchAll(/className=(?:"([^"]+)"|\{`([^`]+)`\}|\{'([^']+)'\})/g)) {
    const raw = (m[1] ?? m[2] ?? m[3]).replace(/\$\{[^}]*\}/g, ' ');
    for (const c of raw.split(/\s+/).filter(Boolean)) {
      if (!used.has(c)) used.set(c, new Set());
      used.get(c).add(f.slice(root.length));
    }
  }
}

const missing = [...used].filter(([c]) => !defined.has(c) && !/^(is|has)-/.test(c)).sort();
for (const [c, where] of missing) console.log(`${c}\t${[...where].join(', ')}`);
console.log(`\n${missing.length} unstyled classes (excluding is-/has- state modifiers)`);

